67	/*!
68	 * \brief Check whether two regions have intersections.
69	 * \param region1 The first region.
70	 * \param region2 The second region.
71	 * \return Whether region1 and region2 have intersections.
72	 */
73	bool MayConflict(const Region &region1, const Region &region2) {
74	  ICHECK(region1.size() == region2.size());
75	  for (size_t i = 0; i < region1.size(); i++) {
76	    Range dim1 = region1[i];
77	    Range dim2 = region2[i];
78	    auto int_set1 = arith::IntSet::FromRange(dim1);
79	    auto int_set2 = arith::IntSet::FromRange(dim2);
80	    if (arith::Intersect({int_set1, int_set2}).IsNothing()) {
81	      return false;
82	    }
83	  }
84	  return true;
85	}
