109	void BufferRegionCollector::HandleTileOp(const TileOperator &tile_op) {
110	  if (tile_op.as<RegionOpNode>()) {
111	    return;
112	  }
113	  if (const auto *parallel = tile_op.as<ParallelOpNode>()) {
114	    BufferRegionCollector nested(buffer_data_to_buffer_, target_);
115	    nested(parallel->GetRoot());
116	    reads_.insert(reads_.end(), nested.GetReads().begin(),
117	                  nested.GetReads().end());
118	    writes_.insert(writes_.end(), nested.GetWrites().begin(),
119	                   nested.GetWrites().end());
120	    is_global_copy_pattern_ =
121	        is_global_copy_pattern_ || nested.GetGlobalCopyPattern();
122	    is_tma_copy_ = is_tma_copy_ || nested.GetTmaCopyPattern();
123	    has_non_copy_tile_op_ = has_non_copy_tile_op_ || nested.HasNonCopyTileOp();
124	    return;
125	  }
126	  AccessRegions access = tile_op->GetAccessRegions();
127	  reads_.insert(reads_.end(), access.reads.begin(), access.reads.end());
128	  writes_.insert(writes_.end(), access.writes.begin(), access.writes.end());
129	  if (const auto *copy = tile_op.as<CopyNode>()) {
130	    if (IsGlobalLikeBuffer(copy->src) && IsSharedBuffer(copy->dst)) {
131	      is_global_copy_pattern_ = true;
132	    }
133	  }
134	  // Im2Col always uses TMA on Hopper.
135	  if (const auto *im2col = tile_op.as<Im2ColOpNode>()) {
136	    if (IsGlobalLikeBuffer(im2col->src_) && IsSharedBuffer(im2col->dst_)) {
137	      is_global_copy_pattern_ = true;
138	      if (TargetIsHopper(target_)) {
139	        is_tma_copy_ = true;
140	      }
141	    }
142	    return;
143	  }
144	  if (!tile_op.as<CopyNode>()) {
145	    has_non_copy_tile_op_ = true;
146	  }
147	}
