149	void BufferRegionCollector::VisitStmt_(const BufferStoreNode *op) {
150	  Buffer store_buffer = op->buffer;
151	  Array<PrimExpr> indices = op->indices;
152	  // convert indices to region
153	  Array<Range> region;
154	  for (const auto &index : indices) {
155	    region.push_back(Range::FromMinExtent(index, 1));
156	  }
157	  auto store_region = BufferRegion(store_buffer, region);
158	  writes_.push_back(store_region);
159	
160	  is_global_read_ = false;
161	  this->VisitExpr(op->value);
162	  if (is_global_read_ && IsSharedBuffer(store_buffer)) {
163	    is_global_copy_pattern_ = true;
164	  }
165	  is_global_read_ = false;
166	}
167	
168	void BufferRegionCollector::VisitExpr_(const BufferLoadNode *op) {
169	  auto load_buffer = op->buffer;
170	  Array<PrimExpr> indices = op->indices;
171	  // convert indices to region
172	  Array<Range> region;
173	  for (const auto &index : indices) {
174	    region.push_back(Range::FromMinExtent(index, 1));
175	  }
176	  auto load_region = BufferRegion(load_buffer, region);
177	  reads_.push_back(load_region);
178	
179	  if (IsGlobalLikeBuffer(op->buffer) && !within_condition_expr_) {
180	    // skip condition expr of if_then_else node
181	    // shared[i] = T.if_then_else(global[i] < n, register_a[i], register_b[i])
182	    // is not a global read shared[i] = T.if_then_else(global[i] < n,
183	    // global_a[i], global_b[i]) is a global read
184	    is_global_read_ = true;
185	  }
186	}
187	
188	void BufferRegionCollector::VisitExpr_(const CallNode *op) {
189	  if (auto tile_op = ParseOperator(GetRef<Call>(op)); tile_op.defined()) {
190	    HandleTileOp(tile_op);
191	    StmtExprVisitor::VisitExpr_(op);
192	    return;
193	  }
194	  if (op->op.same_as(builtin::address_of())) {
195	    BufferRegion buffer_region;
196	    if (const auto *load = op->args[0].as<BufferLoadNode>()) {
197	      buffer_region = BufferRegion::FullRegion(load->buffer);
198	    } else if (const auto *var_node = op->args[0].as<VarNode>()) {
199	      Var data_var = GetRef<Var>(var_node);
200	      auto it = buffer_data_to_buffer_.find(data_var);
201	      if (it != buffer_data_to_buffer_.end()) {
202	        buffer_region = BufferRegion::FullRegion((*it).second);
203	      }
204	    }
205	    if (buffer_region.defined()) {
206	      // because we only care about the buffer itself instead of indices
207	      reads_.push_back(buffer_region);
208	    }
209	  } else if (op->op.same_as(builtin::tvm_access_ptr())) {
210	    const VarNode *buffer_var = op->args[1].as<VarNode>();
211	    ICHECK(buffer_var);
212	    auto it = buffer_data_to_buffer_.find(GetRef<Var>(buffer_var));
213	    if (it != buffer_data_to_buffer_.end()) {
214	      const Buffer &buffer = (*it).second;
215	      const BufferRegion buffer_region = BufferRegion::FullRegion(buffer);
216	      // because we only care about the buffer itself instead of indices
217	      reads_.push_back(buffer_region);
218	    }
219	  } else if (op->op.same_as(builtin::if_then_else())) {
220	    within_condition_expr_ = true;
221	    this->VisitExpr(op->args[0]);
222	    within_condition_expr_ = false;
223	    for (auto i = 1; i < op->args.size(); i++) {
224	      this->VisitExpr(op->args[i]);
225	    }
226	  } else {
227	    StmtExprVisitor::VisitExpr_(op);
228	  }
229	}
230	
231	void BufferRegionCollector::VisitStmt_(const IfThenElseNode *op) {
232	  within_condition_expr_ = true;
233	  this->VisitExpr(op->condition);
234	  within_condition_expr_ = false;
235	  this->VisitStmt(op->then_case);
236	  if (op->else_case.defined()) {
237	    within_condition_expr_ = true;
238	    this->VisitStmt(op->else_case.value());
239	    within_condition_expr_ = false;
240	  }
241	}
