277	  struct ScheduledStmtAnalysis {
278	    size_t original_stmt_count{0};
279	    size_t stage_stmt_count{0};
280	    Array<Stmt> scheduled_stmts;
281	    std::vector<size_t> scheduled_indices;
282	    std::vector<size_t> scheduled_stage_indices;
283	    Array<Integer> replayable_bind_mask;
284	  };
285	
286	  ScheduledStmtAnalysis AnalyzeScheduledStmts(const Array<Stmt> &stmts) const {
287	    BufferSet pipeline_write_buffers = CollectPipelineWriteBuffers(stmts);
288	    ScheduledStmtAnalysis analysis;
289	    analysis.original_stmt_count = stmts.size();
290	    analysis.replayable_bind_mask.reserve(stmts.size());
291	    size_t stage_stmt_index = 0;
292	    for (size_t i = 0; i < stmts.size(); ++i) {
293	      const Stmt &stmt = stmts[i];
294	      if (IsPipelineDeclarationStmt(stmt)) {
295	        continue;
296	      }
297	      bool replayable =
298	          IsReplayableScalarBindStmt(stmt, pipeline_write_buffers);
299	      analysis.replayable_bind_mask.push_back(Integer(replayable ? 1 : 0));
300	      if (replayable) {
301	        ++stage_stmt_index;
302	        continue;
303	      }
304	      analysis.scheduled_indices.push_back(i);
305	      analysis.scheduled_stage_indices.push_back(stage_stmt_index);
306	      analysis.scheduled_stmts.push_back(stmt);
307	      ++stage_stmt_index;
308	    }
309	    analysis.stage_stmt_count = stage_stmt_index;
310	    return analysis;
311	  }
312	
313	  Array<Integer> FilterAnnotationsForScheduledStmts(
314	      const Array<Integer> &annotations,
315	      const ScheduledStmtAnalysis &analysis) const {
316	    if (annotations.size() == analysis.scheduled_stmts.size()) {
317	      return annotations;
318	    }
319	
320	    Array<Integer> filtered;
321	    if (annotations.size() == analysis.stage_stmt_count) {
322	      for (size_t index : analysis.scheduled_stage_indices) {
323	        filtered.push_back(annotations[index]);
324	      }
325	    } else {
326	      ICHECK_EQ(annotations.size(), analysis.original_stmt_count)
327	          << "PipelinePlanning: expected pipeline annotation size to match "
328	             "the scheduled statement count, executable statement count, or "
329	             "original statement count";
330	      for (size_t index : analysis.scheduled_indices) {
331	        filtered.push_back(annotations[index]);
332	      }
333	    }
334	    ICHECK_EQ(filtered.size(), analysis.scheduled_stmts.size());
335	    return filtered;
336	  }
