338	  class SeqStmtFlattener : public StmtFunctor<Array<Stmt>(const Stmt &)> {
339	  public:
340	    using Base = StmtFunctor<Array<Stmt>(const Stmt &)>;
341	
342	    static Array<Stmt> Flatten(const Array<Stmt> &stmts) {
343	      SeqStmtFlattener flattener;
344	      Array<Stmt> flattened;
345	      for (const Stmt &stmt : stmts) {
346	        Array<Stmt> nested = flattener(stmt);
347	        flattened.insert(flattened.end(), nested.begin(), nested.end());
348	      }
349	      return flattened;
350	    }
351	
352	    Array<Stmt> VisitStmt(const Stmt &stmt) final {
353	      if (!stmt.as<SeqStmtNode>()) {
354	        return Array<Stmt>{stmt};
355	      }
356	      return Base::VisitStmt(stmt);
357	    }
358	
359	    Array<Stmt> VisitStmt_(const SeqStmtNode *op) final {
360	      Array<Stmt> flattened;
361	      for (const Stmt &stmt : op->seq) {
362	        Array<Stmt> nested = VisitStmt(stmt);
363	        flattened.insert(flattened.end(), nested.begin(), nested.end());
364	      }
365	      return flattened;
366	    }
