378	/*! \brief Information about a pipeline stage
379	 *
380	 * \param reads Array of buffer regions read by this stage
381	 * \param writes Array of buffer regions written by this stage
382	 * \param original_stmt_index Original position of this stage in the pipeline
383	 * before reordering \param order Current position of this stage in the
384	 * pipeline after reordering (-1 if not yet assigned) \param stage Pipeline
385	 * stage number this operation belongs to (-1 if not yet assigned) \param
386	 * copy_stage Whether this stage is a memory copy operation \param
387	 * last_use_stmt_index Index of the last statement (in original order) that
388	 * uses the results of this stage (-1 if not yet determined). This field is
389	 * crucial for pipeline optimization:
390	 * - For copy stages: indicates the index of the last statement that reads
391	 * from the copied data, helping determine optimal placement of copy
392	 * operations
393	 * - Used to ensure copy operations are scheduled before their consumers
394	 * - A value of -1 means no subsequent statement uses this stage's output
395	 * - This information enables better pipeline scheduling by minimizing data
396	 *   dependencies and maximizing parallelism
397	 */
398	struct PipelineStageInfo {
399	  Array<BufferRegion> reads, writes;
400	  std::unordered_set<const VarNode *> scalar_defs;
401	  std::unordered_set<const VarNode *> scalar_uses;
402	  int original_stmt_index{};
403	  int order = -1, stage = -1;
404	  bool copy_stage = false;
405	  bool tma_copy = false; // true if this copy stage uses TMA (not cp.async)
406	  bool conditional_execution = false;
407	  bool producer_for_copy = false;
408	  int last_use_stmt_index =
409	      -1; // Initialized to -1, indicating no consumers found yet
410	
411	public:
412	  bool IsFirstStage() const { return copy_stage || producer_for_copy; }
413	  bool IsCopyStage() const { return copy_stage; }
414	  bool IsTmaCopy() const { return tma_copy; }
415	  bool IsProducerForCopy() const { return producer_for_copy; }
416	  bool IsLastUseStmtIndexValid() const { return last_use_stmt_index != -1; }
417	};
