449	  bool MayBeConditionallyExecuted(const Stmt &stmt) const {
450	    bool conditional = false;
451	    PostOrderVisit(stmt, [&](const ObjectRef &node) {
452	      if (conditional) {
453	        return;
454	      }
455	      if (const auto *if_then_else = node.as<IfThenElseNode>()) {
456	        conditional = true;
457	        return;
458	      }
459	      if (const auto *realize = node.as<SBlockRealizeNode>()) {
460	        if (!is_one(realize->predicate)) {
461	          conditional = true;
462	        }
463	      }
464	    });
465	    return conditional;
466	  }
