468	  bool IsAsyncProducerCandidate(const PipelineStageInfo &pinfo) const {
469	    if (pinfo.conditional_execution) {
470	      return false;
471	    }
472	    if (pinfo.IsTmaCopy()) {
473	      return false;
474	    }
475	    return pinfo.IsCopyStage();
476	  }
