478	  bool IsPureCopyStmt(const Stmt &stmt) const {
479	    auto is_global_like_buffer = [](const Buffer &buffer) {
480	      return IsGlobalBuffer(buffer) ||
481	             (buffer.defined() && buffer.scope().empty());
482	    };
483	    auto is_pure_raw_copy_value = [&](const PrimExpr &expr,
484	                                      const auto &self) -> bool {
485	      if (const auto *load = expr.as<BufferLoadNode>()) {
486	        return is_global_like_buffer(load->buffer);
487	      }
488	      if (const auto *cast = expr.as<CastNode>()) {
489	        return self(cast->value, self);
490	      }
491	      return false;
492	    };
493	
494	    bool saw_copy = false;
495	    bool saw_non_copy_tile_op = false;
496	    bool saw_non_copy_buffer_store = false;
497	    PostOrderVisit(stmt, [&](const ObjectRef &node) {
498	      if (saw_non_copy_tile_op || saw_non_copy_buffer_store) {
499	        return;
500	      }
501	      if (const auto *store = node.as<BufferStoreNode>()) {
502	        saw_copy = true;
503	        if ((!IsSharedBuffer(store->buffer) &&
504	             !IsLocalBuffer(store->buffer, /*allow_var=*/true)) ||
505	            !is_pure_raw_copy_value(store->value, is_pure_raw_copy_value)) {
506	          saw_non_copy_buffer_store = true;
507	        }
508	        return;
509	      }
510	      const auto *call = node.as<CallNode>();
511	      if (call == nullptr) {
512	        return;
513	      }
514	      auto tile_op = ParseOperator(GetRef<Call>(call));
515	      if (!tile_op.defined()) {
516	        return;
517	      }
518	      if (tile_op.as<RegionOpNode>()) {
519	        return;
520	      }
521	      if (const auto *parallel = tile_op.as<ParallelOpNode>()) {
522	        if (IsPureCopyStmt(parallel->GetRoot())) {
523	          saw_copy = true;
524	        } else {
525	          saw_non_copy_tile_op = true;
526	        }
527	        return;
528	      }
529	      if (tile_op.as<CopyNode>() || tile_op.as<Im2ColOpNode>()) {
530	        saw_copy = true;
531	      } else {
532	        saw_non_copy_tile_op = true;
533	      }
534	    });
535	    return saw_copy && !saw_non_copy_tile_op && !saw_non_copy_buffer_store;
536	  }
