538	  Optional<TileOperator> GetSinglePureCopyTileOp(const Stmt &stmt) const {
539	    Optional<TileOperator> copy_tile_op;
540	    bool saw_non_copy_tile_op = false;
541	    bool saw_multiple_copy_ops = false;
542	    PostOrderVisit(stmt, [&](const ObjectRef &node) {
543	      if (saw_non_copy_tile_op || saw_multiple_copy_ops) {
544	        return;
545	      }
546	      const auto *call = node.as<CallNode>();
547	      if (call == nullptr) {
548	        return;
549	      }
550	      auto tile_op = ParseOperator(GetRef<Call>(call));
551	      if (!tile_op.defined()) {
552	        return;
553	      }
554	      if (tile_op.as<RegionOpNode>()) {
555	        return;
556	      }
557	      if (tile_op.as<CopyNode>() || tile_op.as<Im2ColOpNode>()) {
558	        if (copy_tile_op.defined()) {
559	          saw_multiple_copy_ops = true;
560	          copy_tile_op = Optional<TileOperator>();
561	        } else {
562	          copy_tile_op = tile_op;
563	        }
564	      } else {
565	        saw_non_copy_tile_op = true;
566	        copy_tile_op = Optional<TileOperator>();
567	      }
568	    });
569	    if (saw_non_copy_tile_op || saw_multiple_copy_ops) {
570	      return Optional<TileOperator>();
571	    }
572	    return copy_tile_op;
573	  }
