580	  void ClassifyCopyLikeStage(const Stmt &stmt, PipelineStageInfo *pinfo) const {
581	    ICHECK(pinfo != nullptr);
582	    if (pinfo->conditional_execution) {
583	      return;
584	    }
585	
586	    if (pinfo->copy_stage) {
587	      return;
588	    }
589	
590	    auto copy_tile_op = GetSinglePureCopyTileOp(stmt);
591	    if (!copy_tile_op.defined()) {
592	      return;
593	    }
594	
595	    if (const auto *copy = copy_tile_op.value().as<CopyNode>()) {
596	      if (!IsGlobalLikeBuffer(copy->src) || !IsSharedBuffer(copy->dst)) {
597	        return;
598	      }
599	      pinfo->copy_stage = true;
600	      return;
601	    }
602	
603	    if (const auto *im2col = copy_tile_op.value().as<Im2ColOpNode>()) {
604	      if (!IsGlobalLikeBuffer(im2col->src_) || !IsSharedBuffer(im2col->dst_)) {
605	        return;
606	      }
607	      pinfo->copy_stage = true;
608	      pinfo->tma_copy = TargetIsHopper(target_);
609	    }
610	  }
611	
612	  void AnalyzeCopyLastUse(
613	      std::vector<PipelineStageInfo> *pipeline_stage_infos) const {
614	    for (auto &pinfo : *pipeline_stage_infos) {
615	      if (!pinfo.IsFirstStage()) {
616	        continue;
617	      }
618	
619	      for (int i = pinfo.original_stmt_index + 1;
620	           i < static_cast<int>(pipeline_stage_infos->size()); ++i) {
621	        for (const BufferRegion &read : (*pipeline_stage_infos)[i].reads) {
622	          if (std::find_if(pinfo.writes.begin(), pinfo.writes.end(),
623	                           [&](const BufferRegion &r) {
624	                             return r->buffer == read->buffer &&
625	                                    MayConflict(r->region, read->region);
626	                           }) != pinfo.writes.end()) {
627	            pinfo.last_use_stmt_index = std::max(pinfo.last_use_stmt_index, i);
628	          }
629	        }
630	
631	        if (!pinfo.IsCopyStage()) {
632	          continue;
633	        }
634	
635	        for (const BufferRegion &write : (*pipeline_stage_infos)[i].writes) {
636	          if (std::find_if(pinfo.writes.begin(), pinfo.writes.end(),
637	                           [&](const BufferRegion &r) {
638	                             return r->buffer == write->buffer &&
639	                                    MayConflict(r->region, write->region);
640	                           }) != pinfo.writes.end()) {
641	            LOG(FATAL) << "Pipeline planning error: Multiple writes to "
642	                          "overlapping buffer regions detected. "
643	                       << "Stage " << pinfo.original_stmt_index << " and stage "
644	                       << i << " are both writing to buffer '"
645	                       << write->buffer->name
646	                       << "' with overlapping regions. This is not supported "
647	                          "in pipeline planning.";
648	          }
649	        }
650	      }
651	    }
652	  }
653	
654	  void PropagateBufferProducersForCopy(
655	      std::vector<PipelineStageInfo> *pipeline_stage_infos) const {
656	    struct CopyStageDependencyReadsManager {
657	      std::vector<BufferRegion> regions;
658	
659	      void AddUnique(const BufferRegion &region) {
660	        for (const BufferRegion &copy_read : regions) {
661	          if (region->buffer.same_as(copy_read->buffer)) {
662	            return;
663	          }
664	        }
665	        regions.push_back(region);
666	      }
667	
668	      bool Contains(const BufferRegion &region) const {
669	        for (const BufferRegion &copy_read : regions) {
670	          if (region->buffer.same_as(copy_read->buffer)) {
671	            return true;
672	          }
673	        }
674	        return false;
675	      }
676	
677	      size_t Size() const { return regions.size(); }
678	    };
679	
680	    CopyStageDependencyReadsManager copy_stage_dependency_reads_mgr;
681	
682	    for (const auto &pinfo : *pipeline_stage_infos) {
683	      if (pinfo.IsCopyStage()) {
684	        for (const BufferRegion &read : pinfo.reads) {
685	          copy_stage_dependency_reads_mgr.AddUnique(read);
686	        }
687	      }
688	    }
689	
690	    const size_t max_iterations = (pipeline_stage_infos->size() * 4) + 16;
691	    size_t iter_count = 0;
692	
693	    for (auto &pinfo : *pipeline_stage_infos) {
694	      if (!pinfo.IsCopyStage()) {
695	        continue;
696	      }
697	      auto original_copy_stmt_index = pinfo.original_stmt_index;
698	      bool updated = true;
699	      while (updated) {
700	        updated = false;
701	        for (auto &pinfo_inner : *pipeline_stage_infos) {
702	          if (pinfo_inner.IsCopyStage()) {
703	            continue;
704	          }
705	          if (pinfo_inner.original_stmt_index >= original_copy_stmt_index) {
706	            break;
707	          }
708	
709	          bool should_prepare = false;
710	          for (const BufferRegion &write : pinfo_inner.writes) {
711	            if (copy_stage_dependency_reads_mgr.Contains(write)) {
712	              should_prepare = true;
713	              break;
714	            }
715	          }
716	          if (should_prepare && !pinfo_inner.IsProducerForCopy()) {
717	            pinfo_inner.producer_for_copy = true;
718	            updated = true;
719	          }
720	          if (should_prepare) {
721	            for (const BufferRegion &read : pinfo_inner.reads) {
722	              size_t before = copy_stage_dependency_reads_mgr.Size();
723	              copy_stage_dependency_reads_mgr.AddUnique(read);
724	              if (copy_stage_dependency_reads_mgr.Size() > before) {
725	                updated = true;
726	              }
727	            }
728	          }
729	        }
730	        iter_count++;
731	        if (iter_count > max_iterations) {
732	          LOG(FATAL)
733	              << "Pipeline planning: Exceeded maximum iterations ("
734	              << max_iterations << ") in copy stage dependency propagation. "
735	              << "This may indicate a cyclic or pathological dependency graph.";
736	        }
737	      }
738	    }
739	  }
740	
741	  std::unordered_map<const VarNode *, int> BuildScalarDefMap(
742	      const std::vector<PipelineStageInfo> &pipeline_stage_infos) const {
743	    std::unordered_map<const VarNode *, int> scalar_def_to_stmt;
744	    for (int i = 0; i < static_cast<int>(pipeline_stage_infos.size()); ++i) {
745	      for (const VarNode *var : pipeline_stage_infos[i].scalar_defs) {
746	        scalar_def_to_stmt.emplace(var, i);
747	      }
748	    }
749	    return scalar_def_to_stmt;
750	  }
751	
752	  void PropagateScalarProducersForCopy(
753	      std::vector<PipelineStageInfo> *pipeline_stage_infos) const {
754	    auto scalar_def_to_stmt = BuildScalarDefMap(*pipeline_stage_infos);
755	    const size_t max_iterations = (pipeline_stage_infos->size() * 4) + 16;
756	    size_t iter_count = 0;
757	    bool updated = true;
758	
759	    auto update_producer = [](PipelineStageInfo *producer,
760	                              int consumer_last_use) -> bool {
761	      if (consumer_last_use < 0) {
762	        return false;
763	      }
764	      bool changed = false;
765	      if (!producer->producer_for_copy) {
766	        producer->producer_for_copy = true;
767	        producer->last_use_stmt_index = consumer_last_use;
768	        changed = true;
769	      } else if (!producer->IsLastUseStmtIndexValid() ||
770	                 consumer_last_use < producer->last_use_stmt_index) {
771	        producer->last_use_stmt_index = consumer_last_use;
772	        changed = true;
773	      }
774	      return changed;
775	    };
776	
777	    while (updated) {
778	      updated = false;
779	      for (int consumer_idx = 0;
780	           consumer_idx < static_cast<int>(pipeline_stage_infos->size());
781	           ++consumer_idx) {
782	        const auto &consumer = (*pipeline_stage_infos)[consumer_idx];
783	        if (!(consumer.IsFirstStage() && consumer.IsLastUseStmtIndexValid())) {
784	          continue;
785	        }
786	        for (const VarNode *var : consumer.scalar_uses) {
787	          auto it = scalar_def_to_stmt.find(var);
788	          if (it == scalar_def_to_stmt.end() || it->second == consumer_idx) {
789	            continue;
790	          }
791	          auto &producer = (*pipeline_stage_infos)[it->second];
792	          if (producer.IsCopyStage()) {
793	            continue;
794	          }
795	          updated |= update_producer(&producer, consumer.last_use_stmt_index);
796	        }
797	      }
798	      if (++iter_count > max_iterations) {
799	        LOG(FATAL) << "Pipeline planning: Exceeded maximum iterations while "
800	                      "propagating scalar producers for copy stages.";
801	      }
802	    }
803	  }
804	
805	  void ValidateScalarDependencies(
806	      const std::vector<PipelineStageInfo> &pipeline_stage_infos) const {
807	    auto scalar_def_to_stmt = BuildScalarDefMap(pipeline_stage_infos);
808	    for (int consumer_idx = 0;
809	         consumer_idx < static_cast<int>(pipeline_stage_infos.size());
810	         ++consumer_idx) {
811	      const auto &consumer = pipeline_stage_infos[consumer_idx];
812	      for (const VarNode *var : consumer.scalar_uses) {
813	        auto it = scalar_def_to_stmt.find(var);
814	        if (it == scalar_def_to_stmt.end() || it->second == consumer_idx) {
815	          continue;
816	        }
817	        const auto &producer = pipeline_stage_infos[it->second];
818	        ICHECK_EQ(producer.stage, consumer.stage)
819	            << "Pipeline planning error: scalar dependency from statement "
820	            << producer.original_stmt_index << " to statement "
821	            << consumer.original_stmt_index
822	            << " crosses pipeline stages. Scheduled scalar Bind statements "
823	               "must stay in the same stage as their consumers.";
824	        if (producer.stage == consumer.stage) {
825	          ICHECK_LT(producer.order, consumer.order)
826	              << "Pipeline planning error: scalar dependency from statement "
827	              << producer.original_stmt_index << " to statement "
828	              << consumer.original_stmt_index
829	              << " is reordered within the same pipeline stage.";
830	        }
831	      }
832	    }
833	  }
834	
835	  bool EmitImplicitAsyncAnnotations(
836	      const std::vector<PipelineStageInfo> &pipeline_stage_infos,
837	      Map<String, Any> *annotations) const {
838	    if (!TargetHasAsyncCopy(target_) || !use_async_copy_) {
839	      return false;
840	    }
841	
842	    std::vector<int> async_group_ids(pipeline_stage_infos.size(), -1);
843	    std::vector<int> stmt_indices_by_order(pipeline_stage_infos.size());
844	    std::iota(stmt_indices_by_order.begin(), stmt_indices_by_order.end(), 0);
845	    std::stable_sort(stmt_indices_by_order.begin(), stmt_indices_by_order.end(),
846	                     [&](int lhs, int rhs) {
847	                       if (pipeline_stage_infos[lhs].order !=
848	                           pipeline_stage_infos[rhs].order) {
849	                         return pipeline_stage_infos[lhs].order <
850	                                pipeline_stage_infos[rhs].order;
851	                       }
852	                       return lhs < rhs;
853	                     });
854	
855	    int next_async_group_id = 0;
856	    std::map<std::pair<int, int>, int> implicit_group_ids;
857	    for (int stmt_idx : stmt_indices_by_order) {
858	      const auto &pinfo = pipeline_stage_infos[stmt_idx];
859	      if (!IsAsyncProducerCandidate(pinfo)) {
860	        continue;
861	      }
862	      auto key = std::make_pair(pinfo.stage, pinfo.last_use_stmt_index);
863	      auto [it, inserted] =
864	          implicit_group_ids.emplace(key, next_async_group_id);
865	      if (inserted) {
866	        ++next_async_group_id;
867	      }
868	      async_group_ids[stmt_idx] = it->second;
869	    }
870	
871	    if (next_async_group_id == 0) {
872	      return false;
873	    }
874	
875	    std::vector<Integer> async_producers;
876	    std::vector<Integer> async_producer_groups;
877	    async_producers.reserve(pipeline_stage_infos.size());
878	    async_producer_groups.reserve(pipeline_stage_infos.size());
879	    std::unordered_set<int> async_stage_ids;
880	    for (size_t i = 0; i < pipeline_stage_infos.size(); ++i) {
881	      bool is_async_producer = async_group_ids[i] != -1;
882	      async_producers.push_back(Integer(is_async_producer ? 1 : 0));
883	      async_producer_groups.push_back(Integer(async_group_ids[i]));
884	      if (is_async_producer) {
885	        async_stage_ids.insert(pipeline_stage_infos[i].stage);
886	      }
887	    }
888	
889	    annotations->Set(kPipelineAsyncProducers, Array<Integer>(async_producers));
890	    annotations->Set(kPipelineAsyncProducerGroups,
891	                     Array<Integer>(async_producer_groups));
892	
893	    std::vector<int> sorted_async_stage_ids(async_stage_ids.begin(),
894	                                            async_stage_ids.end());
895	    std::sort(sorted_async_stage_ids.begin(), sorted_async_stage_ids.end());
896	    std::vector<Integer> async_stages;
897	    async_stages.reserve(sorted_async_stage_ids.size());
898	    for (int stage_id : sorted_async_stage_ids) {
899	      async_stages.push_back(Integer(stage_id));
900	    }
901	    annotations->Set(s_tir::attr::software_pipeline_async_stages,
902	                     Array<Integer>(async_stages));
903	    return true;
904	  }
905	
906	  void MaybeAnnotateLegacyAsyncPipelineLoop(const Array<Stmt> &pipeline_stmts,
907	                                            const Array<Integer> &order_array,
908	                                            const Array<Integer> &stage_array,
909	                                            Map<String, Any> *annotations) {
910	    if (!TargetHasAsyncCopy(target_) || !use_async_copy_) {
911	      return;
912	    }
913	    ICHECK_EQ(pipeline_stmts.size(), order_array.size());
914	    ICHECK_EQ(pipeline_stmts.size(), stage_array.size());
915	
916	    std::vector<PipelineStageInfo> pipeline_stage_infos;
917	    pipeline_stage_infos.reserve(pipeline_stmts.size());
918	    for (size_t i = 0; i < pipeline_stmts.size(); ++i) {
919	      auto pinfo = MakePipelineStageInfo(pipeline_stmts[i], i);
920	      ClassifyCopyLikeStage(pipeline_stmts[i], &pinfo);
921	      pinfo.order = static_cast<int>(order_array[i]->value);
922	      pinfo.stage = static_cast<int>(stage_array[i]->value);
923	      if (!pinfo.IsCopyStage() && !pinfo.conditional_execution &&
924	          pinfo.stage == 0) {
925	        bool reads_global = false;
926	        bool writes_shared = false;
927	        for (const BufferRegion &read : pinfo.reads) {
928	          if (IsGlobalLikeBuffer(read->buffer)) {
929	            reads_global = true;
930	            break;
931	          }
932	        }
933	        for (const BufferRegion &write : pinfo.writes) {
934	          if (IsSharedBuffer(write->buffer)) {
935	            writes_shared = true;
936	            break;
937	          }
938	        }
939	        if (reads_global && writes_shared) {
940	          pinfo.copy_stage = true;
941	        }
942	      }
943	      pipeline_stage_infos.push_back(std::move(pinfo));
944	    }
945	
946	    AnalyzeCopyLastUse(&pipeline_stage_infos);
947	    EmitImplicitAsyncAnnotations(pipeline_stage_infos, annotations);
948	  }
949	
950	  PipelineStageInfo MakePipelineStageInfo(Stmt stmt, int idx) {
951	    SBlock block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
952	                 /*name_hint=*/"",
953	                 /*body*/ std::move(stmt));
954	    auto collector = BufferRegionCollector(buffer_data_to_buffer_, target_);
955	    collector(block);
956	    PipelineStageInfo pinfo;
957	    pinfo.reads = std::move(collector.GetReads());
958	    pinfo.writes = std::move(collector.GetWrites());
959	    auto [scalar_defs, scalar_uses] =
960	        ScalarUseDefCollector::Collect(block->body);
961	    pinfo.scalar_defs = std::move(scalar_defs);
962	    pinfo.scalar_uses = std::move(scalar_uses);
963	    pinfo.original_stmt_index = idx;
964	    pinfo.conditional_execution = MayBeConditionallyExecuted(block->body);
965	    bool pure_copy_stage =
966	        collector.GetGlobalCopyPattern() && IsPureCopyStmt(block->body);
967	    pinfo.copy_stage = pure_copy_stage;
968	    pinfo.tma_copy = pure_copy_stage && !pinfo.conditional_execution &&
969	                     collector.GetTmaCopyPattern();
970	    ClassifyCopyLikeStage(block->body, &pinfo);
971	    return pinfo;
972	  }
