1058	                                                                 analysis);
1059	  }
1060	
1061	  Stmt VisitStmt_(const ForNode *loop) final {
1062	    auto order_anno = loop->annotations.Get("tl_pipeline_order");
1063	    auto stage_anno = loop->annotations.Get("tl_pipeline_stage");
1064	    auto num_stages_anno = loop->annotations.Get("num_stages");
1065	    if (order_anno && stage_anno) {
1066	      auto order_array = Downcast<Array<Integer>>(order_anno.value());
1067	      auto stage_array = Downcast<Array<Integer>>(stage_anno.value());
1068	
1069	      Map<String, Any> annotations;
1070	      for (const auto &[key, value] : loop->annotations) {
1071	        if (key != "tl_pipeline_order" && key != "tl_pipeline_stage") {
1072	          annotations.Set(key, value);
1073	        }
1074	      }
1075	      if (TargetHasAsyncCopy(target_) && use_async_copy_) {
1076	        // Legacy explicit stage/order annotations do not carry per-statement
1077	        // async producer metadata yet, so keep the previous stage-level
1078	        // behavior as a fallback for these loops.
1079	        annotations.Set(s_tir::attr::software_pipeline_async_stages,
1080	                        Array<Integer>{0});
1081	      }
1082	      Array<Stmt> pipeline_body_stmts = NormalizePipelineBody(loop->body);
1083	      Array<Stmt> pipeline_stmts =
1084	          SeqStmtFlattener::Flatten(pipeline_body_stmts);
1085	      ScheduledStmtAnalysis analysis = AnalyzeScheduledStmts(pipeline_stmts);
1086	      ICHECK(!analysis.scheduled_stmts.empty())
1087	          << "PipelinePlanning: explicit pipeline annotations have no "
1088	             "schedulable statements after removing replayable scalar Bind "
1089	             "statements";
1090	      Array<Integer> filtered_order_array =
1091	          FilterAnnotationsForScheduledStmts(order_array, analysis);
1092	      Array<Integer> filtered_stage_array =
1093	          FilterAnnotationsForScheduledStmts(stage_array, analysis);
1094	      annotations.Set(s_tir::attr::software_pipeline_order,
1095	                      filtered_order_array);
1096	      annotations.Set(s_tir::attr::software_pipeline_stage,
1097	                      filtered_stage_array);
1098	      if (pipeline_stmts.size() == pipeline_body_stmts.size()) {
1099	        bool flatten_preserved_original_order = true;
1100	        for (size_t i = 0; i < pipeline_stmts.size(); ++i) {
1101	          if (!pipeline_stmts[i].same_as(pipeline_body_stmts[i])) {
1102	            flatten_preserved_original_order = false;
1103	            break;
1104	          }
1105	        }
1106	        if (flatten_preserved_original_order &&
1107	            std::any_of(analysis.replayable_bind_mask.begin(),
1108	                        analysis.replayable_bind_mask.end(),
1109	                        [](const Integer &value) { return !is_zero(value); })) {
1110	          annotations.Set(kPipelineReplayableScalarBinds,
1111	                          analysis.replayable_bind_mask);
1112	        }
1113	      }
1114	      MaybeAnnotateLegacyAsyncPipelineLoop(analysis.scheduled_stmts,
1115	                                           filtered_order_array,
1116	                                           filtered_stage_array, &annotations);
1117	      auto for_node = GetRef<For>(loop);
1118	      auto *n = for_node.CopyOnWrite();
1119	      n->annotations = annotations;
1120	      n->body = MakePipelineBody(pipeline_body_stmts);
1121	      return for_node;
1122	    }
1123	
1124	    if (!num_stages_anno)
1125	      return StmtExprMutator::VisitStmt_(loop);
1126	    int num_stages = num_stages_anno->as<IntImmNode>()->value;
1127	    // Skip software pipelining on ROCm targets where async-copy pipelining
1128	    // has not been validated.  Currently only gfx950 (CDNA4 / MI350) supports
1129	    // the full HIP async-copy pipeline path.  gfx942 (CDNA3 / MI300X) has
1130	    // async-copy hardware but the software pipeline for that target has not
1131	    // been validated yet, so it falls back to a plain sequential loop as well.
1132	    // RDNA targets have no async-copy support at all and also fall back.
1133	    if (TargetIsRocm(target_) && !TargetIsGfx950(target_) && num_stages >= 1) {
1134	      // Strip the "num_stages" annotation before recursing so that downstream
1135	      // passes (InjectSoftwarePipeline, MultiVersionBufferRewriter, etc.) do
1136	      // not treat this loop as pipelined.  Leaving the annotation in place
1137	      // would cause those passes to multi-version shared buffers and inject
1138	      // cp.async / barrier code that is incompatible with the plain sequential
1139	      // execution path chosen here.
1140	      auto stripped = GetRef<For>(loop);
1141	      Map<String, Any> annotations;
1142	      for (const auto &[key, value] : loop->annotations) {
1143	        if (key != "num_stages") {
1144	          annotations.Set(key, value);
1145	        }
1146	      }
1147	      stripped.CopyOnWrite()->annotations = annotations;
1148	      return StmtExprMutator::VisitStmt_(stripped.get());
1149	    }
1150	    Array<Stmt> pipeline_body_stmts = NormalizePipelineBody(loop->body);
1151	
1152	    ICHECK(num_stages >= 1);
1153	    ICHECK(loop->kind == ForKind::kSerial);
1154	
1155	    // Flatten nested SeqStmts so pipeline planning can assign stages to the
1156	    // normalized top-level statement list.
1157	    Array<Stmt> flat_stmts = SeqStmtFlattener::Flatten(pipeline_body_stmts);
1158	    ScheduledStmtAnalysis analysis = AnalyzeScheduledStmts(flat_stmts);
1159	    ICHECK(!analysis.scheduled_stmts.empty())
1160	        << "PipelinePlanning: loop has no schedulable statements after "
1161	           "removing replayable scalar Bind statements";
1162	
1163	    std::vector<PipelineStageInfo> pipeline_stage_infos;
1164	    for (size_t i = 0; i < analysis.scheduled_stmts.size(); i++) {
1165	      auto pinfo = MakePipelineStageInfo(analysis.scheduled_stmts[i], i);
1166	      pipeline_stage_infos.push_back(std::move(pinfo));
1167	    }
1168	
1169	    // Some statements before a copy are not copy operations themselves, but
1170	    // they prepare buffers that the copy must read.  A common example is
1171	    // producer-side initialization before a conditional or partial copy:
1172	    //
1173	    //   fill(shared, 0)        // writes shared
1174	    //   copy(global, shared)   // may rely on the initialized values
1175	    //
1176	    // If the copy is moved to the producer side, the fill must move with it;
1177	    // otherwise the copy could observe an uninitialized or wrong shared-buffer
1178	    // value.  PropagateBufferProducersForCopy computes a buffer-level backward
1179	    // dependency closure from copy-stage reads to earlier non-copy writes and
1180	    // marks those statements as `producer_for_copy`.  They then participate in
1181	    // the producer-stage scheduling just like the copy stages they prepare.
1182	    PropagateBufferProducersForCopy(&pipeline_stage_infos);
1183	
1184	    // Analysis use-def chain to determine last_use_stmt_index for copy
1185	    // operations This step is critical for pipeline optimization as it
1186	    // identifies the index of the last statement that consumes data produced by
1187	    // copy stages, enabling optimal placement of copy operations in the
1188	    // pipeline schedule.
1189	    AnalyzeCopyLastUse(&pipeline_stage_infos);
1190	
1191	    PropagateScalarProducersForCopy(&pipeline_stage_infos);
1192	
1193	    // Making stages and orders
1194	    int order_idx = 0;
1195	    // Stage 1. Create pipeline stages and assign order
1196	    for (auto &pinfo : pipeline_stage_infos) {
1197	      // Skip elements that must be in first stage:
1198	      // 1. Copy stages (with active last_use_stmt_index) - these need special
1199	      // handling
1200	      //    because they have consumers that depend on their data
1201	      // 2. All Producer stages for copy stages.
1202	      if (pinfo.IsFirstStage() && pinfo.IsLastUseStmtIndexValid()) {
1203	        continue;
1204	      }
1205	
1206	      // Main logic stage assignment:
1207	      // - Increment order index
1208	      // - Assign to new stage (current num_stages)
1209	      pinfo.order = order_idx++;
1210	      pinfo.stage = num_stages;
1211	
1212	      // Schedule copy stages that have this stage as their last consumer
1213	      // This ensures copy operations are placed right before their final
1214	      // consumer for optimal pipeline efficiency
1215	      for (auto &pinfo_1 : pipeline_stage_infos) {
1216	        if ((pinfo_1.IsFirstStage() &&
1217	             pinfo_1.last_use_stmt_index == pinfo.original_stmt_index)) {
1218	          pinfo_1.order = order_idx++;
1219	          pinfo_1.stage = 0; // Copy stages are typically assigned to stage 0
1220	        }
1221	      }
1222	    }
1223	
1224	    ICHECK(size_t(order_idx) == pipeline_stage_infos.size())
1225	        << "The number of stages should be equal to the number of pipeline "
1226	           "stages. "
1227	        << "Got " << order_idx << " stages and " << pipeline_stage_infos.size()
1228	        << " pipeline stages.";
1229	
1230	    // Step 2. if all the copy is at the end of the order, we can move these
1231	    // copy to the beginning of the order and shrink the stage offset by 1.
1232	    int copy_stage_at_end = [&]() {
1233	      int copy_stage_cnt = 0;
1234	      int copy_order_min = pipeline_stage_infos.size();
1235	      int non_copy_order_max = 0;
1236	      for (auto &pinfo : pipeline_stage_infos) {
1237	        if (pinfo.IsFirstStage()) {
1238	          copy_stage_cnt++;
1239	          copy_order_min = std::min(copy_order_min, pinfo.order);
1240	        } else {
1241	          non_copy_order_max = std::max(non_copy_order_max, pinfo.order);
1242	        }
1243	      }
1244	      if (copy_order_min > non_copy_order_max)
1245	        return copy_stage_cnt;
1246	      return -1;
1247	    }();
1248	    if (copy_stage_at_end > 0 && num_stages >= 2) {
1249	      for (auto &pinfo : pipeline_stage_infos) { // move copy to the beginning
1250	        pinfo.order =
1251	            (pinfo.order + copy_stage_at_end) % pipeline_stage_infos.size();
1252	        if (!pinfo.IsCopyStage() && !pinfo.IsProducerForCopy())
1253	          pinfo.stage--;
1254	      }
1255	    }
1256	
1257	    ValidateScalarDependencies(pipeline_stage_infos);
1258	
1259	    // Finally, make the pipeline annotation
1260	    Map<String, Any> annotations;
1261	    for (const auto &[key, value] : loop->annotations) {
1262	      if (key != "num_stages") {
1263	        annotations.Set(key, value);
1264	      }
1265	    }
1266	    // Preserve the original TileLang pipelining depth for downstream scheduling
1267	    // (e.g. generated async-copy wait placement). We intentionally do NOT
1268	    // keep the legacy key "num_stages" here because multiple downstream passes
1269	    // (e.g. internal buffer versioning / warp specialization) treat it as an
1270	    // active pipeline marker and do not support nested pipelines.
1271	    annotations.Set("tl_pipelined_num_stages", Integer(num_stages));
1272	
1273	    std::vector<Integer> orders, stages;
1274	    orders.reserve(pipeline_stage_infos.size());
1275	    stages.reserve(pipeline_stage_infos.size());
1276	    for (auto &pinfo : pipeline_stage_infos) {
1277	      orders.push_back(pinfo.order);
1278	      stages.push_back(pinfo.stage);
1279	    }
1280	
1281	    annotations.Set(s_tir::attr::software_pipeline_stage,
1282	                    Array<Integer>(stages));
1283	    annotations.Set(s_tir::attr::software_pipeline_order,
1284	                    Array<Integer>(orders));
1285	    if (std::any_of(analysis.replayable_bind_mask.begin(),
1286	                    analysis.replayable_bind_mask.end(),
1287	                    [](const Integer &value) { return !is_zero(value); })) {
1288	      annotations.Set(kPipelineReplayableScalarBinds,
1289	                      analysis.replayable_bind_mask);
1290	    }
1291	
1292	    // Propagate per-statement TMA eligibility so InjectSoftwarePipeline can
1293	    // rewrite TMA copies to use pipeline-level barrier management.
1294	    {
1295	      std::vector<Integer> tma_copies;
1296	      tma_copies.reserve(pipeline_stage_infos.size());
1297	      bool has_tma_copy = false;
1298	      for (auto &pinfo : pipeline_stage_infos) {
1299	        bool IsTmaCopy = pinfo.IsTmaCopy();
1300	        has_tma_copy = has_tma_copy || IsTmaCopy;
1301	        tma_copies.push_back(Integer(IsTmaCopy ? 1 : 0));
1302	      }
1303	      if (has_tma_copy) {
1304	        annotations.Set(kPipelineTmaCopies, Array<Integer>(tma_copies));
1305	      }
1306	    }
1307	
1308	    EmitImplicitAsyncAnnotations(pipeline_stage_infos, &annotations);
1309	
1310	    // Reconstruct the loop body with the flattened SeqStmt so that
1311	    // InjectSoftwarePipeline sees the correct number of pipeline stages.
1312	    Stmt new_body = MakePipelineBody(flat_stmts);
1313	
1314	    return For(loop->loop_var, loop->min, loop->extent, loop->kind, new_body,
1315	               loop->thread_binding, annotations);
1316	  }
1317	
1318	  Stmt VisitStmt_(const SBlockNode *op) final {
1319	    for (const auto &buffer : op->alloc_buffers) {
1320	      buffer_data_to_buffer_.Set(buffer->data, buffer);
1321	    }
1322	    SBlock block = Downcast<SBlock>(StmtExprMutator::VisitStmt_(op));
1323	    for (const auto &buffer : op->alloc_buffers) {
1324	      buffer_data_to_buffer_.erase(buffer->data);
1325	    }
1326	    return block;
1327	  }
1328	
1329	  Map<Var, Buffer> buffer_data_to_buffer_;
1330	  Target target_;
1331	  bool use_async_copy_{};
1332	};
1333	
1334	tvm::transform::Pass PipelinePlanning() {
1335	  using namespace tirx::transform;
1336	  auto pass_func = [=](PrimFunc f, const IRModule &m, PassContext ctx) {
1337	    bool use_async_copy =
1338	        ctx->GetConfig<Bool>("tirx.use_async_copy", Bool(true)).value();
1339	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
1340	    if (TargetIsMaca(target.value())) {
1341	      use_async_copy = false;
1342	    }
1343	    PrimFuncNode *fptr = f.CopyOnWrite();
1344	    fptr->body = PipelinePlanner::Substitute(f, use_async_copy);
1345	    return f;
1346	  };
1347	  return CreatePrimFuncPass(pass_func, 0, "tl.PipelinePlanning", {});
1348	}
1349	
1350	TVM_FFI_STATIC_INIT_BLOCK() {
1351	  namespace refl = reflection;
1352	  refl::GlobalDef().def("tl.transform.PipelinePlanning", PipelinePlanning);
1353	}
1354	
1355	} // namespace tl
1356	} // namespace tvm
