127	bool ShapesEqual(const Array<PrimExpr> &lhs, const Array<PrimExpr> &rhs,
128	                 arith::Analyzer *analyzer) {
129	  if (lhs.size() != rhs.size()) {
130	    return false;
131	  }
132	  for (size_t i = 0; i < lhs.size(); ++i) {
133	    if (!analyzer->CanProveEqual(lhs[i], rhs[i])) {
134	      return false;
135	    }
136	  }
137	  return true;
138	}
