196	  void VisitExpr_(const CallNode *op) final {
197	    if (auto tile_op = ParseOperator(GetRef<Call>(op)); tile_op.defined()) {
198	      AccessRegions access = tile_op->GetAccessRegions();
199	      for (const auto &region : access.reads) {
200	        AddBuffer(region->buffer);
