346	class AsyncCommitWaitAttrLowerer : public StmtExprMutator {
347	public:
348	  static Stmt Lower(const Stmt &stmt) {
349	    AsyncCommitWaitAttrLowerer lowerer;
350	    return lowerer.VisitStmt(stmt);
351	  }
352	
353	private:
354	  Stmt VisitStmt_(const AttrStmtNode *op) final {
355	    if (op->attr_key == s_tir::attr::async_commit_queue_scope) {
356	      Stmt body = VisitStmt(op->body);
357	      Stmt commit =
358	          Evaluate(Call(DataType::Handle(), builtin::ptx_commit_group(), {}));
359	      if (is_no_op(body)) {
360	        return commit;
361	      }
362	      return SeqStmt({body, commit});
363	    }
364	    if (op->attr_key == s_tir::attr::async_wait_queue_scope) {
365	      auto wait_attrs = GetAsyncWaitAttributes(op);
366	      Stmt body = op->body;
367	      if (const auto *inner = op->body.as<AttrStmtNode>()) {
368	        if (inner->attr_key == s_tir::attr::async_wait_inflight_count) {
369	          body = inner->body;
370	        }
371	      }
372	      body = VisitStmt(body);
373	      Stmt wait = Evaluate(Call(DataType::Handle(), builtin::ptx_wait_group(),
374	                                {wait_attrs.second}));
375	      if (is_no_op(body)) {
376	        return wait;
377	      }
378	      return SeqStmt({wait, body});
379	    }
380	    if (op->attr_key == s_tir::attr::async_wait_inflight_count) {
381	      return VisitStmt(op->body);
382	    }
383	    return StmtExprMutator::VisitStmt_(op);
384	  }
385	};
