520	/*!
521	 * \brief Build the dependency graph among a array of blocks.
522	 * \param[in] blocks The array of blocks.
523	 * \param[out] dep_src2dst Optional, a map to store dependency edges from the
524	 * source to the destination. \param[out] dep_dst2src Optional, a map to store
525	 * dependency edges from the destination to the source.
526	 */
527	void BuildDependencyGraph(const Array<SBlock> &blocks,
528	                          BlockDependencyGraph *dep_src2dst,
529	                          BlockDependencyGraph *dep_dst2src) {
530	  std::unordered_map<Var, Array<SBlock>, ObjectPtrHash, ObjectPtrEqual>
531	      buffer_writers;
532	
533	  for (const SBlock &block : blocks) {
534	    for (const BufferRegion &read : block->reads) {
535	      auto it = buffer_writers.find(read->buffer->data);
536	      if (it != buffer_writers.end()) {
537	        for (const SBlock &writer : it->second) {
538	          if (dep_src2dst != nullptr) {
539	            (*dep_src2dst)[writer].push_back(block);
540	          }
541	          if (dep_dst2src != nullptr) {
542	            (*dep_dst2src)[block].push_back(writer);
543	          }
544	        }
545	      }
546	    }
547	    for (const BufferRegion &write : block->writes) {
548	      buffer_writers[write->buffer->data].push_back(block);
549	    }
550	  }
551	}
