661	/// Rewrite barrier references: expand indices and rewrite parity.
662	class BarrierIndexRewriter : public StmtExprMutator {
663	public:
664	  BarrierIndexRewriter(const BufferMap &old_to_new,
665	                       const BufferShapeMap &old_shapes, PrimExpr stage_expr,
666	                       PrimExpr parity_cycle, Var loop_var, PrimExpr loop_min)
667	      : old_to_new_(old_to_new), old_shapes_(old_shapes),
668	        stage_expr_(std::move(stage_expr)),
669	        parity_cycle_(std::move(parity_cycle)), loop_var_(std::move(loop_var)),
670	        loop_min_(std::move(loop_min)) {}
671	
672	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
673	    BufferLoad load = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
674	    auto it = old_to_new_.find(load->buffer);
675	    if (it != old_to_new_.end()) {
676	      auto *n = load.CopyOnWrite();
677	      PrimExpr old_size = old_shapes_.at(load->buffer);
678	      n->buffer = it->second;
679	      n->indices.Set(0, stage_expr_ * old_size + n->indices[0]);
680	    }
681	    return load;
682	  }
683	
684	  Stmt VisitStmt_(const BufferStoreNode *op) final {
685	    BufferStore store = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
686	    auto it = old_to_new_.find(store->buffer);
687	    if (it != old_to_new_.end()) {
688	      auto *n = store.CopyOnWrite();
689	      PrimExpr old_size = old_shapes_.at(store->buffer);
690	      n->buffer = it->second;
691	      n->indices.Set(0, stage_expr_ * old_size + n->indices[0]);
692	    }
693	    return store;
694	  }
695	
696	  PrimExpr VisitExpr_(const CallNode *op) final {
697	    Call call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
698	
699	    // Rewrite barrier refs inside annotations (e.g., tma_copy "barrier").
700	    bool anno_changed = false;
701	    Map<String, ObjectRef> new_annos = call->annotations;
702	    for (const auto &[key, val] : call->annotations) {
703	      if (auto load = val.as<BufferLoadNode>()) {
704	        auto it = old_to_new_.find(load->buffer);
705	        if (it != old_to_new_.end()) {
706	          PrimExpr old_size = old_shapes_.at(load->buffer);
707	          auto new_load = BufferLoad(
708	              it->second, {stage_expr_ * old_size + load->indices[0]});
709	          new_annos.Set(key, new_load);
710	          anno_changed = true;
711	        }
712	      }
713	    }
714	    if (anno_changed) {
715	      call = Call(call->dtype, call->op, call->args, new_annos, call->span);
716	    }
717	
718	    // Rewrite mbarrier_wait_parity parity argument.
719	    if (call->op.same_as(mbarrier_wait_parity()) && call->args.size() >= 2) {
720	      if (auto load = call->args[0].as<BufferLoadNode>()) {
721	        // Check if the barrier ref (possibly already rewritten above)
722	        // targets one of our expanded barriers.
723	        bool is_expanded = false;
724	        for (const auto &kv : old_to_new_) {
725	          if (load->buffer.same_as(kv.second)) {
726	            is_expanded = true;
727	            break;
728	          }
729	        }
730	        if (is_expanded) {
731	          // Compute initial-phase offset from the user's original parity.
732	          arith::Analyzer analyzer;
733	          PrimExpr user_parity = call->args[1];
734	          PrimExpr user_parity_at_min = analyzer.Simplify(
735	              tirx::Substitute(user_parity, {{loop_var_, loop_min_}}));
736	          // New parity = (iteration_block + offset) % 2
737	          PrimExpr offset = IntImm(DataType::Int(32), 0);
738	          if (const int64_t *imm = as_const_int(user_parity_at_min)) {
739	            offset = IntImm(DataType::Int(32), *imm % 2);
740	          }
741	          PrimExpr new_parity = FloorMod(parity_cycle_ + offset, 2);
742	          Array<PrimExpr> new_args = call->args;
743	          new_args.Set(1, new_parity);
744	          return Call(call->dtype, call->op, new_args, call->annotations,
745	                      call->span);
746	        }
747	      }
748	    }
749	    return call;
750	  }
751	
752	private:
753	  const BufferMap &old_to_new_;
754	  const BufferShapeMap &old_shapes_;
755	  PrimExpr stage_expr_;
756	  PrimExpr parity_cycle_;
757	  Var loop_var_;
758	  PrimExpr loop_min_;
759	};
760	
761	/// Expand all shared.barrier buffers in the pipeline body from [N] to
762	/// [N * num_stages], rewrite barrier indices to include stage offset, and
763	/// rewrite mbarrier_wait_parity parity expressions.
764	///
765	/// This is the unified barrier multi-versioning path that replaces the old
766	/// late barrier-only fixup in OptimizeForTarget.
767	/// Returns a map of old-to-new barrier buffers for outer block alloc_buffers
768	/// update.
769	Map<Buffer, Buffer> ExpandPipelineBarriers(
770	    Array<SBlock> &original_order, PipelineInfo &pipeline_info,
771	    Map<Var, Buffer> &buffer_data_to_buffer, BufferSet &allocated_buffers,
772	    Array<Buffer> &block_local_allocs, Array<Buffer> &pipeline_allocs,
773	    Var loop_var, PrimExpr loop_min, int num_stages) {
774	  if (num_stages <= 1)
775	    return {};
776	
777	  // Only expand barriers that have explicit ptx_arrive_barrier calls in the
778	  // loop body.  This distinguishes pipeline synchronization barriers (where
779	  // arrive/wait are user-managed and need per-stage slots) from barriers
780	  // whose arrival is managed internally by tile-ops (e.g., tcgen05 MMA
781	  // arrive barriers) - those should NOT be pipeline-expanded.
782	  // ISP-created pipeline_mbar is handled specially: it's always in
783	  // block_local_allocs and was just created, so include it too.
784	  BufferSet local_barrier_set;
785	  for (const Buffer &buf : block_local_allocs) {
786	    if (buf.scope() == "shared.barrier" ||
787	        buf.scope() == "shared.cluster_barrier")
788	      local_barrier_set.insert(buf);
789	  }
790	
791	  // Find barriers that have explicit ptx_arrive_barrier calls.
792	  class ArriveBarrierDetector : public StmtExprVisitor {
793	  public:
794	    BufferSet arrived_;
795	    void VisitExpr_(const CallNode *op) final {
796	      if (op->op.same_as(builtin::ptx_arrive_barrier()) && !op->args.empty()) {
797	        if (auto load = op->args[0].as<BufferLoadNode>()) {
798	          arrived_.insert(load->buffer);
799	        }
800	      }
801	      StmtExprVisitor::VisitExpr_(op);
802	    }
803	  };
804	  ArriveBarrierDetector arrive_det;
805	  for (const auto &block : original_order) {
806	    arrive_det(block->body);
807	  }
808	
809	  std::vector<Buffer> all_referenced =
810	      BarrierBufferCollector::Collect(original_order);
811	  std::vector<Buffer> barriers;
812	  for (const Buffer &buf : all_referenced) {
813	    // Include if: (a) it's an ISP-created local barrier, OR
814	    //             (b) it has explicit ptx_arrive_barrier calls.
815	    if (local_barrier_set.count(buf) || arrive_det.arrived_.count(buf)) {
816	      barriers.push_back(buf);
817	    }
818	  }
819	  if (barriers.empty())
820	    return {};
821	
822	  PrimExpr ns = IntImm(DataType::Int(32), num_stages);
823	  PrimExpr stage_expr = FloorMod(loop_var - loop_min, ns);
824	  PrimExpr parity_cycle = FloorMod(FloorDiv(loop_var - loop_min, ns), 2);
825	
826	  auto replace_in_array = [](Array<Buffer> &arr, const Buffer &old_buf,
827	                             const Buffer &new_buf) {
828	    for (size_t i = 0; i < arr.size(); ++i) {
829	      if (arr[i].same_as(old_buf)) {
830	        arr.Set(i, new_buf);
831	      }
832	    }
833	  };
834	
835	  // Create expanded buffer for each barrier.
836	  BufferMap old_to_new;
837	  BufferShapeMap old_shapes;
838	  for (const Buffer &buf : barriers) {
839	    old_shapes[buf] = buf->shape[0];
840	    ObjectPtr<BufferNode> new_node = make_object<BufferNode>(*(buf.get()));
841	    new_node->shape = {PrimExpr(num_stages) * buf->shape[0]};
842	    Buffer new_buf(new_node);
843	    old_to_new[buf] = new_buf;
844	
845	    // Update all maps and alloc arrays.
846	    buffer_data_to_buffer.Set(buf->data, new_buf);
847	    allocated_buffers.erase(buf);
848	    allocated_buffers.insert(new_buf);
849	    replace_in_array(block_local_allocs, buf, new_buf);
850	    replace_in_array(pipeline_allocs, buf, new_buf);
851	  }
852	
853	  // Rewrite all blocks.
854	  BarrierIndexRewriter rewriter(old_to_new, old_shapes, stage_expr,
855	                                parity_cycle, loop_var, loop_min);
856	  for (size_t i = 0; i < original_order.size(); ++i) {
857	    SBlock old_block = original_order[i];
858	    Stmt new_body = rewriter(old_block->body);
859	    if (!new_body.same_as(old_block->body)) {
860	      // Also rewrite alloc_buffers in the block (barriers may be allocated
861	      // here).
862	      Array<Buffer> new_allocs;
863	      for (const Buffer &ab : old_block->alloc_buffers) {
864	        auto it = old_to_new.find(ab);
865	        new_allocs.push_back(it != old_to_new.end() ? it->second : ab);
866	      }
867	      SBlock new_block(old_block->iter_vars, old_block->reads,
868	                       old_block->writes, old_block->name_hint, new_body,
869	                       old_block->init, new_allocs, old_block->match_buffers,
870	                       old_block->annotations);
871	      PipelineAnnotation anno = pipeline_info.at(old_block);
872	      pipeline_info.erase(old_block);
873	      pipeline_info.emplace(new_block, anno);
874	      original_order.Set(i, new_block);
875	    }
876	  }
877	
878	  // Return the old-to-new mapping for outer block alloc_buffers update.
879	  Map<Buffer, Buffer> result;
880	  for (const auto &[old_buf, new_buf] : old_to_new) {
881	    result.Set(old_buf, new_buf);
882	  }
883	  return result;
884	}
