996	/*!
997	 * \brief Rewriter for the body of the software pipeline. This pass inserts
998	 * `floormod` to indices of the remapped buffer to select the version
999	 * corresponding to the pipeline stage.
1000	 */
1001	class PipelineBodyRewriter : public StmtExprMutator {
1002	public:
1003	  /*!
1004	   * \brief Constructor of PipelineBodyRewriter.
1005	   * \param buffer_data_to_buffer The map from buffer data to buffer.
1006	   * \param buffer_remap The map from original buffer to the buffer with updated
1007	   * shape for multi-versioning in the software pipeline. \param pipeline_loop
1008	   * The original loop to be software pipelined. \param access_all_versions
1009	   * Whether all versions the buffers in the software pipeline are accessed.
1010	   * This will be used to update block access region. In the prologue and
1011	   * epilogue of a two-stage software pipeline, only one version of these
1012	   * buffers are accessed.
1013	   */
1014	  PipelineBodyRewriter(const Map<Var, Buffer> &buffer_data_to_buffer,
1015	                       const Map<Buffer, Buffer> &buffer_remap,
1016	                       For pipeline_loop, bool access_all_versions)
1017	      : buffer_data_to_buffer_(buffer_data_to_buffer),
1018	        buffer_remap_(buffer_remap), pipeline_loop_(std::move(pipeline_loop)),
1019	        access_all_versions_(access_all_versions) {}
1020	
1021	private:
1022	  BufferRegion
1023	  RewritePipelineBufferRegion(const BufferRegion &buffer_region) const {
1024	    auto it = buffer_remap_.find(buffer_region->buffer);
1025	    if (it != buffer_remap_.end()) {
1026	      Region new_region = buffer_region->region;
1027	      const Buffer &new_buffer = (*it).second;
1028	      // For pipeline buffers, relax the access region of the first dimension to
1029	      // full extent if access_all_versions == true
1030	      Range accessed_version =
1031	          access_all_versions_
1032	              ? Range::FromMinExtent(0, new_buffer->shape[0])
1033	              : Range::FromMinExtent(
1034	                    floormod((pipeline_loop_->loop_var - pipeline_loop_->min),
1035	                             new_buffer->shape[0]),
1036	                    Integer(1));
1037	      new_region.insert(new_region.begin(), accessed_version);
1038	      return BufferRegion(new_buffer, new_region);
1039	    }
1040	    return buffer_region;
1041	  }
1042	
1043	  PrimExpr RewriteBufferAccess(const Call &call,
1044	                               const std::vector<int> &arg_indices) {
1045	    auto product = [](const Array<PrimExpr> &input) {
1046	      return foldl(
1047	          [](PrimExpr a, PrimExpr b, Span span) {
1048	            return mul(std::move(a), std::move(b), std::move(span));
1049	          },
1050	          make_const(DataType::Int(32), 1), input);
1051	    };
1052	    Array<PrimExpr> new_args = call->args;
1053	    for (int i : arg_indices) {
1054	      auto buffer_var = Downcast<Var>(call->args[i]);
1055	      auto buf_it = buffer_data_to_buffer_.find(buffer_var);
1056	      if (buf_it == buffer_data_to_buffer_.end()) {
1057	        continue;
1058	      }
1059	      const Buffer &buffer = (*buf_it).second;
1060	      auto it = buffer_remap_.find(buffer);
1061	      if (it != buffer_remap_.end()) {
1062	        const Buffer &new_buffer = (*it).second;
1063	        const PrimExpr &old_index = call->args[i + 1];
1064	        PrimExpr offset;
1065	        if (new_buffer->strides.empty()) {
1066	          offset = product(buffer->shape);
1067	        } else {
1068	          offset = new_buffer->strides[0];
1069	        }
1070	        PrimExpr new_index =
1071	            old_index +
1072	            floormod((pipeline_loop_->loop_var - pipeline_loop_->min),
1073	                     new_buffer->shape[0]) *
1074	                offset;
1075	        new_args.Set(i + 1, new_index);
1076	      }
1077	    }
1078	    return Call(call->dtype, call->op, new_args, call->annotations, call->span);
1079	  }
1080	
1081	  Stmt VisitStmt_(const SBlockNode *op) final {
1082	    for (const Buffer &alloc_buffer : op->alloc_buffers) {
1083	      buffer_data_to_buffer_.Set(alloc_buffer->data, alloc_buffer);
1084	    }
1085	    SBlock block = Downcast<SBlock>(StmtExprMutator::VisitStmt_(op));
1086	    SBlockNode *n = block.CopyOnWrite();
1087	    n->reads.MutateByApply([this](const BufferRegion &buffer_region) {
1088	      return RewritePipelineBufferRegion(buffer_region);
1089	    });
1090	    n->writes.MutateByApply([this](const BufferRegion &buffer_region) {
1091	      return RewritePipelineBufferRegion(buffer_region);
1092	    });
1093	    for (const Buffer &alloc_buffer : op->alloc_buffers) {
1094	      buffer_data_to_buffer_.erase(alloc_buffer->data);
1095	    }
1096	    return block;
1097	  }
1098	
1099	  Stmt VisitStmt_(const BufferStoreNode *op) final {
1100	    BufferStore store = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
1101	    auto it = buffer_remap_.find(store->buffer);
1102	    if (it == buffer_remap_.end()) {
1103	      return store;
1104	    }
1105	    const Buffer &new_buffer = (*it).second;
1106	    auto *n = store.CopyOnWrite();
1107	    n->buffer = new_buffer;
1108	    PrimExpr version = floormod(
1109	        (pipeline_loop_->loop_var - pipeline_loop_->min), new_buffer->shape[0]);
1110	    n->indices.insert(n->indices.begin(), version);
1111	    return store;
1112	  }
1113	
1114	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
1115	    BufferLoad load = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
1116	    auto it = buffer_remap_.find(load->buffer);
1117	    if (it == buffer_remap_.end()) {
1118	      return load;
1119	    }
1120	    const Buffer &new_buffer = (*it).second;
1121	    auto *n = load.CopyOnWrite();
1122	    n->buffer = new_buffer;
1123	    PrimExpr version = floormod(
1124	        (pipeline_loop_->loop_var - pipeline_loop_->min), new_buffer->shape[0]);
1125	    n->indices.insert(n->indices.begin(), version);
1126	    return load;
1127	  }
1128	
1129	  PrimExpr VisitExpr_(const CallNode *op) final {
1130	    Call call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
1131	    if (call->op.same_as(builtin::tvm_access_ptr())) {
1132	      return RewriteBufferAccess(call, {1});
1133	    }
1134	    if (call->op.same_as(RegionOp::Get()) && call->args.size() >= 2) {
1135	      if (auto load = call->args[0].as<BufferLoadNode>()) {
1136	        size_t num_extents = call->args.size() - 2;
1137	        if (load->indices.size() == num_extents + 1) {
1138	          Array<PrimExpr> new_args;
1139	          new_args.push_back(call->args[0]);
1140	          new_args.push_back(call->args[1]);
1141	          new_args.push_back(IntImm(DataType::Int(32), 1));
1142	          for (size_t i = 2; i < call->args.size(); ++i) {
1143	            new_args.push_back(call->args[i]);
1144	          }
1145	          return Call(call->dtype, call->op, new_args, call->annotations,
1146	                      call->span);
1147	        }
1148	      }
1149	    }
1150	    return call;
1151	  }
1152	
1153	  Map<Var, Buffer> buffer_data_to_buffer_;
1154	  Map<Buffer, Buffer> buffer_remap_;
1155	  For pipeline_loop_;
1156	  bool access_all_versions_;
1157	};
1158	
1159	/*!
1160	 * \brief Rewriter for the software pipeline that rewrite a loop into a
1161	 * pipelined one.
1162	 */
1163	class PipelineRewriter : public StmtExprMutator {
1164	public:
1165	  /*!
1166	   * \brief Constructor of PipelineRewriter.
1167	   * \param buffer_data_to_buffer The map from buffer data to buffer.
1168	   * \param pipeline_allocs All buffers that need multi-versioning in the
1169	   * pipeline. This includes buffers allocated in the pipeline block and
1170	   * buffers allocated in outer blocks that are used in the pipeline.
1171	   * \param local_allocs Buffers that are allocated in the pipeline block
1172	   * itself. These buffers will be re-allocated in the rewritten block.
1173	   * Buffers in pipeline_allocs but not in local_allocs are allocated in outer
1174	   * blocks and should not be re-allocated.
1175	   * \param pipeline_loop The original loop to be software pipelined.
1176	   * \param pipeline_info The pipeline annotation information.
1177	   * \param scalar_binding_blocks Replayable scalar Bind statements from the
1178	   * pipeline body.
1179	   */
1180	  PipelineRewriter(Map<Var, Buffer> buffer_data_to_buffer,
1181	                   const Array<Buffer> &pipeline_allocs,
1182	                   const Array<Buffer> &local_allocs, const For &pipeline_loop,
1183	                   const PipelineInfo &pipeline_info,
1184	                   const Array<SBlock> &scalar_binding_blocks,
1185	                   Optional<Target> target)
1186	      : buffer_data_to_buffer_(std::move(buffer_data_to_buffer)),
1187	        pipeline_allocs_(pipeline_allocs), local_allocs_(local_allocs),
1188	        pipeline_loop_(pipeline_loop), pipeline_info_(pipeline_info),
1189	        scalar_binding_blocks_(scalar_binding_blocks),
1190	        target_(std::move(target)) {}
1191	
1192	  Stmt BuildPipeline() {
1193	    // Step 1: Analyze accesses to the buffers in the pipeline and compute the
1194	    // number of versions need to maintain for each buffer.
1195	    std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
1196	        infos = GetBufferAccessInfo();
1197	    for (const Buffer &buffer : pipeline_allocs_) {
1198	      auto it = infos.find(buffer);
1199	      if (it == infos.end()) {
1200	        // Buffer is not accessed in the pipeline blocks, skip it
1201	        continue;
1202	      }
1203	      int num_versions = ComputeBufferVersions(buffer, it->second);
1204	      if (num_versions > 1) {
1205	        buffer_remap_.Set(buffer, RewriteAllocBuffer(buffer, num_versions));
1206	      }
1207	    }
1208	    std::vector<std::pair<int, SBlock>> ordered_blocks;
1209	    for (const auto &[block, anno] : pipeline_info_) {
1210	      ordered_blocks.emplace_back(anno.order, block);
1211	    }
1212	    std::sort(
1213	        ordered_blocks.begin(), ordered_blocks.end(),
1214	        [](const auto &lhs, const auto &rhs) { return lhs.first < rhs.first; });
1215	    for (const auto &[_, block] : ordered_blocks) {
1216	      ordered_stmts_.push_back(block);
1217	    }
1218	    CollectScalarBindings();
1219	
1220	    // Step 2: Emit the pipeline prologue, body and epilogue.
1221	    Optional<Integer> pipeline_num_stages =
1222	        GetPipelineNumStages(pipeline_loop_.get());
1223	    Stmt prologue = EmitImpl(pipeline_loop_->min,
1224	                             pipeline_loop_->min + max_stage_, true, true);
1225	    Stmt body =
1226	        EmitImpl(pipeline_loop_->min + max_stage_,
1227	                 pipeline_loop_->min + pipeline_loop_->extent, false, false);
1228	    Stmt epilogue = EmitImpl(
1229	        pipeline_loop_->min + pipeline_loop_->extent,
1230	        pipeline_loop_->min + pipeline_loop_->extent + max_stage_, true, true);
1231	
1232	    Array<Stmt> pipeline_parts;
1233	    for (const Stmt &part : {prologue, body, epilogue}) {
1234	      for (const Stmt &stmt : FlattenTopLevelSeq(part)) {
1235	        pipeline_parts.push_back(stmt);
1236	      }
1237	    }
1238	
1239	    Stmt stmt = pipeline_parts.size() == 1 ? pipeline_parts[0]
1240	                                           : SeqStmt(pipeline_parts);
1241	    stmt = AsyncPipelineLoopWaitRelaxer(this)(stmt);
1242	    Array<Stmt> relaxed_pipeline_parts = FlattenTopLevelSeq(stmt);
1243	    relaxed_pipeline_parts =
1244	        RelaxTrailingConsumerWaits(std::move(relaxed_pipeline_parts),
1245	                                   PipelinedRetainGroups(pipeline_num_stages));
1246	    stmt = relaxed_pipeline_parts.size() == 1 ? relaxed_pipeline_parts[0]
1247	                                              : SeqStmt(relaxed_pipeline_parts);
1248	
1249	    // Step 3: Make a new block only when the rewritten pipeline owns local
1250	    // allocations.  When all buffers are already allocated by an outer block
1251	    // (the common TileLang kernel-root case), an extra synthetic scope would
1252	    // only carry a very large inferred read/write region and make the IR hard
1253	    // to inspect.
1254	    if (local_allocs_.empty()) {
1255	      return stmt;
1256	    }
1257	
1258	    // Only include buffers that are locally allocated in the pipeline block.
1259	    // Buffers from outer blocks will be handled separately.
1260	    Array<Buffer> alloc_buffers;
1261	    for (const auto &alloc : local_allocs_) {
1262	      alloc_buffers.push_back(buffer_remap_.Get(alloc).value_or(alloc));
1263	      buffer_data_to_buffer_.erase(alloc->data);
1264	    }
1265	    SBlock block = MakeBlock(stmt, buffer_data_to_buffer_);
1266	    block.CopyOnWrite()->alloc_buffers = std::move(alloc_buffers);
1267	    return SBlockRealize({}, Bool(true), block);
1268	  }
1269	
1270	  /*!
1271	   * \brief Get the buffer remapping created during pipeline rewriting.
1272	   * This is used to update alloc_buffers in outer blocks.
1273	   */
1274	  const Map<Buffer, Buffer> &GetBufferRemap() const { return buffer_remap_; }
1275	
1276	private:
1277	  struct ScalarBinding {
1278	    Var var;
1279	    PrimExpr value;
1280	    Span span;
1281	  };
1282	
1283	  using ScalarBindingMap =
1284	      std::unordered_map<Var, size_t, ObjectPtrHash, ObjectPtrEqual>;
1285	
1286	  void CollectScalarBindings() {
1287	    scalar_bindings_.clear();
1288	    scalar_binding_map_.clear();
1289	    for (const SBlock &block : scalar_binding_blocks_) {
1290	      if (const auto *bind = block->body.as<BindNode>()) {
1291	        if (!scalar_binding_map_.count(bind->var)) {
1292	          scalar_binding_map_.emplace(bind->var, scalar_bindings_.size());
1293	          scalar_bindings_.push_back({bind->var, bind->value, bind->span});
1294	        }
1295	      }
1296	    }
1297	  }
1298	
1299	  VarSet FindScalarBindingUses(const Array<Var> &undefined_vars) const {
1300	    VarSet uses;
1301	    for (const Var &var : undefined_vars) {
1302	      if (scalar_binding_map_.count(var)) {
1303	        uses.insert(var);
1304	      }
1305	    }
1306	    return uses;
1307	  }
1308	
1309	  VarSet FindScalarBindingUses(const Stmt &stmt) const {
1310	    return FindScalarBindingUses(UndefinedVars(stmt, Array<Var>{}));
1311	  }
1312	
1313	  VarSet FindScalarBindingUses(const PrimExpr &expr) const {
1314	    return FindScalarBindingUses(UndefinedVars(expr));
1315	  }
1316	
1317	  void AppendScalarBinding(size_t binding_index, VarSet *emitted,
1318	                           VarSet *visiting,
1319	                           std::vector<size_t> *binding_indices) const {
1320	    const ScalarBinding &binding = scalar_bindings_[binding_index];
1321	    if (emitted->count(binding.var)) {
1322	      return;
1323	    }
1324	    ICHECK(!visiting->count(binding.var))
1325	        << "InjectSoftwarePipeline: cyclic scalar Bind dependency involving "
1326	        << binding.var;
1327	
1328	    visiting->insert(binding.var);
1329	    VarSet deps = FindScalarBindingUses(binding.value);
1330	    for (const ScalarBinding &candidate : scalar_bindings_) {
1331	      if (!deps.count(candidate.var)) {
1332	        continue;
1333	      }
1334	      auto it = scalar_binding_map_.find(candidate.var);
1335	      ICHECK(it != scalar_binding_map_.end());
1336	      AppendScalarBinding(it->second, emitted, visiting, binding_indices);
1337	    }
1338	    visiting->erase(binding.var);
1339	
1340	    emitted->insert(binding.var);
1341	    binding_indices->push_back(binding_index);
1342	  }
1343	
1344	  std::vector<size_t> RequiredScalarBindings(const Stmt &stmt) const {
1345	    std::vector<size_t> binding_indices;
1346	    if (scalar_bindings_.empty()) {
1347	      return binding_indices;
1348	    }
1349	
1350	    VarSet uses = FindScalarBindingUses(stmt);
1351	    if (uses.empty()) {
1352	      return binding_indices;
1353	    }
1354	
1355	    VarSet emitted;
1356	    VarSet visiting;
1357	    for (const ScalarBinding &binding : scalar_bindings_) {
1358	      if (!uses.count(binding.var)) {
1359	        continue;
1360	      }
1361	      auto it = scalar_binding_map_.find(binding.var);
1362	      ICHECK(it != scalar_binding_map_.end());
1363	      AppendScalarBinding(it->second, &emitted, &visiting, &binding_indices);
1364	    }
1365	    return binding_indices;
1366	  }
1367	
1368	  Stmt RewriteScalarBindingForAccess(size_t binding_index,
1369	                                     const PrimExpr &access_index) {
1370	    const ScalarBinding &binding = scalar_bindings_[binding_index];
1371	    Stmt bind = Bind(binding.var, binding.value, binding.span);
1372	    bind = PipelineBodyRewriter(buffer_data_to_buffer_, buffer_remap_,
1373	                                pipeline_loop_, max_stage_ != 1)(bind);
1374	    bind = Substitute(bind, {{pipeline_loop_->loop_var, access_index}});
1375	    return bind;
1376	  }
1377	
1378	  SBlock ReplayScalarBindings(SBlock block, const PrimExpr &access_index) {
1379	    std::vector<size_t> binding_indices = RequiredScalarBindings(block->body);
1380	    if (binding_indices.empty()) {
1381	      return block;
1382	    }
1383	
1384	    Array<Stmt> seq;
1385	    for (size_t binding_index : binding_indices) {
1386	      seq.push_back(RewriteScalarBindingForAccess(binding_index, access_index));
1387	    }
1388	    for (const Stmt &stmt : FlattenTopLevelSeq(block->body)) {
1389	      seq.push_back(stmt);
1390	    }
1391	
1392	    SBlockNode *n = block.CopyOnWrite();
1393	    n->body = SeqStmt(seq);
1394	    return MakeBlock(SBlockRealize({}, Bool(true), block),
1395	                     buffer_data_to_buffer_);
1396	  }
