1437	  /*!
1438	   * \brief Check whether two regions have intersections.
1439	   * \param region1 The first region.
1440	   * \param region2 The second region.
1441	   * \return Whether region1 and region2 have intersections.
1442	   */
1443	  bool MayConflict(const Region &region1, const Region &region2) {
1444	    ICHECK(region1.size() == region2.size());
1445	    for (size_t i = 0; i < region1.size(); i++) {
1446	      Range dim1 = region1[i];
1447	      Range dim2 = region2[i];
1448	      auto int_set1 = arith::IntSet::FromRange(dim1);
1449	      auto int_set2 = arith::IntSet::FromRange(dim2);
1450	      if (arith::Intersect({int_set1, int_set2}).IsNothing()) {
1451	        return false;
1452	      }
1453	    }
1454	    return true;
1455	  }
