1457	  /*!
1458	   * \brief Compute the number of versions need to maintain for buffer accessed
1459	   * in the software pipeline.
1460	   *
1461	   * This method applies liveness analysis to the target buffer to compute the
1462	   * number of versions need to maintain during the software pipeline.
1463	   * Annotation `attr::double_buffer_scope` is handled here which provides a way
1464	   * to override the result of the analysis. Additional double buffering in the
1465	   * software pipeline can be useful to eliminate synchronizations in GPU
1466	   * devices.
1467	   *
1468	   * \param buffer The target buffer
1469	   * \param buffer_info The access information of the target buffer.
1470	   * \return The number of versions required for the target buffer.
1471	   */
1472	  int ComputeBufferVersions(const Buffer &buffer,
1473	                            const BufferAccessInfo &buffer_info) {
1474	    if (buffer_info.def == -1) {
1475	      // Keep the original number of versions as buffers defined outside the
1476	      // software pipeline should not be mutated.
1477	      return 1;
1478	    }
1479	
1480	    // `use - def + 1` is a upper bound of the needed versions
1481	    // We optimize a few case where the number of versions can be smaller than
1482	    // the upper bound
1483	    int num_versions = buffer_info.use - buffer_info.def + 1;
1484	    if (num_versions >= 2) {
1485	      // A special case when `use - def + 1 == 2`. Double buffering is only
1486	      // needed in this case when these exists a reader block_i and a writer
1487	      // block_j such that order(block_i) < order(block_j) and stage(block_i) <
1488	      // stage(block_j) and the access regions of block_i and block_j overlap.
1489	      bool need_multi_version = false;
1490	      for (const auto &pair1 : pipeline_info_) {
1491	        const SBlock &writer_block = pair1.first;
1492	        const auto &writer_info = pair1.second;
1493	
1494	        auto it1 = std::find_if(writer_block->writes.begin(),
1495	                                writer_block->writes.end(),
1496	                                [&](const BufferRegion &buffer_region) {
1497	                                  return buffer_region->buffer.same_as(buffer);
1498	                                });
1499	        if (it1 == writer_block->writes.end()) {
1500	          continue;
1501	        }
1502	
1503	        for (const auto &pair2 : pipeline_info_) {
1504	          const SBlock &reader_block = pair2.first;
1505	          const auto &reader_info = pair2.second;
1506	          auto it2 = std::find_if(
1507	              reader_block->reads.begin(), reader_block->reads.end(),
1508	              [&](const BufferRegion &buffer_region) {
1509	                return buffer_region->buffer.same_as(buffer);
1510	              });
1511	          if (it2 == reader_block->reads.end()) {
1512	            continue;
1513	          }
1514	          if (writer_info.order < reader_info.order &&
1515	              writer_info.stage < reader_info.stage &&
1516	              MayConflict((*it1)->region, (*it2)->region)) {
1517	            need_multi_version = true;
1518	            break;
1519	          }
1520	        }
1521	      }
1522	      if (!need_multi_version) {
1523	        num_versions--;
1524	      }
1525	    }
1526	    return num_versions;
1527	  }
