1529	  /*!
1530	   * \brief Rewrite buffer allocation to keep multiple versions of original
1531	   * buffer for pipelined accesses. \param buffer The buffer to be resized.
1532	   * \param num_versions The number of versions to keep.
1533	   * \return The resized buffer.
1534	   */
1535	  Buffer RewriteAllocBuffer(const Buffer &buffer, int num_versions) {
1536	    ObjectPtr<BufferNode> new_buffer = make_object<BufferNode>(*(buffer.get()));
1537	    new_buffer->shape.insert(new_buffer->shape.begin(), PrimExpr(num_versions));
1538	    if (!new_buffer->strides.empty()) {
1539	      ICHECK(new_buffer->strides.size() + 1 == new_buffer->shape.size());
1540	      PrimExpr stride_0 = new_buffer->strides[0] * new_buffer->shape[1];
1541	      new_buffer->strides.insert(new_buffer->strides.begin(), stride_0);
1542	    }
1543	    return Buffer(new_buffer);
1544	  }
