1627	  struct DeterministicNoWaitCommitEffect {
1628	    bool deterministic{true};
1629	    bool has_wait{false};
1630	    int commit_groups{0};
1631	
1632	    static DeterministicNoWaitCommitEffect Unknown() {
1633	      DeterministicNoWaitCommitEffect effect;
1634	      effect.deterministic = false;
1635	      return effect;
1636	    }
1637	
1638	    static DeterministicNoWaitCommitEffect Wait() {
