1742	  Optional<PrimExpr>
1743	  ComputePipelineMbarPhaseExpr(const PrimExpr &normalized_access_index,
1744	                               const Optional<Integer> &pipeline_num_stages) {
1745	    if (!pipeline_num_stages) {
1746	      return Optional<PrimExpr>();
1747	    }
1748	    PrimExpr parity_expr;
1749	    if (pipeline_num_stages.value().IntValue() <= 1) {
1750	      parity_expr =
1751	          FloorMod(normalized_access_index, IntImm(DataType::Int(32), 2));
1752	    } else {
1753	      PrimExpr ns =
1754	          IntImm(DataType::Int(32), pipeline_num_stages.value().IntValue());
1755	      parity_expr = FloorMod(FloorDiv(normalized_access_index, ns),
1756	                             IntImm(DataType::Int(32), 2));
1757	    }
1758	    return analyzer_.Simplify(parity_expr);
1759	  }
