1820	  class HeadAsyncSyncAnalyzer
1821	      : public StmtFunctor<HeadAsyncSyncInfo(const Stmt &)> {
1822	  public:
1823	    static HeadAsyncSyncInfo Analyze(const PipelineRewriter *rewriter,
1824	                                     const Stmt &stmt, HeadSeqMode seq_mode) {
1825	      HeadAsyncSyncAnalyzer analyzer(rewriter, seq_mode);
1826	      return analyzer(stmt);
