1829	    HeadAsyncSyncAnalyzer(const PipelineRewriter *rewriter,
1830	                          HeadSeqMode seq_mode)
1831	        : rewriter_(rewriter), seq_mode_(seq_mode) {}
1832	
1833	    HeadAsyncSyncInfo VisitStmt_(const AttrStmtNode *op) final {
1834	      if (IsAsyncWaitQueueScope(op)) {
1835	        if (auto wait_n = rewriter_->TryGetStaticAsyncWaitCount(op)) {
1836	          return {HeadAsyncSyncKind::kWaitStatic, *wait_n};
1837	        }
1838	        return {HeadAsyncSyncKind::kWaitDynamic, 0};
1839	      }
1840	      if (IsAsyncCommitQueueScope(op)) {
1841	        return {HeadAsyncSyncKind::kCommit, 0};
1842	      }
1843	      if (IsAsyncWaitInflightCount(op)) {
1844	        return {HeadAsyncSyncKind::kBlocked, 0};
1845	      }
1846	      return VisitStmt(op->body);
1847	    }
1848	
1849	    HeadAsyncSyncInfo VisitStmt_(const SeqStmtNode *op) final {
1850	      if (op->seq.empty()) {
1851	        return {};
1852	      }
1853	      if (seq_mode_ == HeadSeqMode::kSingletonOnly && op->seq.size() != 1) {
1854	        return {HeadAsyncSyncKind::kBlocked, 0};
1855	      }
1856	      return VisitStmt(op->seq[0]);
1857	    }
1858	
1859	    HeadAsyncSyncInfo VisitStmt_(const SBlockNode *op) final {
1860	      return VisitStmt(op->body);
1861	    }
1862	
1863	    HeadAsyncSyncInfo VisitStmt_(const SBlockRealizeNode *op) final {
1864	      if (is_one(op->predicate)) {
1865	        return VisitStmt(op->block->body);
1866	      }
1867	      return {HeadAsyncSyncKind::kBlocked, 0};
1868	    }
