2272	  Stmt MaybeRelaxLoopWaits(const For &loop, int pre_outstanding_lb) const {
2273	    int retain = PipelinedRetainGroups(GetPipelineNumStages(loop.get()));
2274	    if (retain <= 0 || !loop.defined()) {
2275	      return loop;
2276	    }
2277	    const auto *seq = loop->body.as<SeqStmtNode>();
2278	    if (!seq || seq->seq.empty()) {
2279	      return loop;
2280	    }
2281	
2282	    Array<Stmt> body = seq->seq;
2283	    bool changed = false;
2284	    int outstanding_lb = std::max(0, pre_outstanding_lb);
2285	    int groups_since_wait_lb = 0;
2286	    bool seen_wait_boundary = false;
2287	
2288	    for (int i = 0, n = static_cast<int>(body.size()); i < n; ++i) {
2289	      ClassifiedAsyncSyncStmt cls = ClassifySimpleAsyncSyncStmt(body[i]);
2290	      if (cls.kind == AsyncSyncStmtKind::kCommit) {
2291	        ++outstanding_lb;
2292	        ++groups_since_wait_lb;
2293	        continue;
2294	      }
2295	      if (cls.kind == AsyncSyncStmtKind::kWaitDynamic) {
2296	        seen_wait_boundary = true;
2297	        outstanding_lb = 0;
2298	        groups_since_wait_lb = 0;
2299	        continue;
2300	      }
2301	      if (cls.kind == AsyncSyncStmtKind::kWaitStatic) {
2302	        int effective_wait_n = cls.wait_n;
2303	        if (cls.wait_n == 0) {
2304	          int groups_after_wait_lb =
2305	              GuaranteedNewGroupsBeforeNextWait(body, i + 1);
2306	          int per_sync_groups = groups_since_wait_lb;
2307	          bool uses_head_fallback =
2308	              (per_sync_groups == 0 && !seen_wait_boundary);
2309	          if (uses_head_fallback) {
2310	            per_sync_groups = 1;
2311	          }
2312	          int candidate_wait_n = std::max(0, retain * per_sync_groups);
2313	          bool enough_pre_outstanding =
2314	              !uses_head_fallback || outstanding_lb >= (candidate_wait_n + 1);
2315	          if (candidate_wait_n > 0 && enough_pre_outstanding &&
2316	              (!uses_head_fallback || groups_after_wait_lb > 0)) {
2317	            Optional<Stmt> rewritten_wait =
2318	                RewriteWaitStaticInSimpleWrapper(body[i], candidate_wait_n);
2319	            if (rewritten_wait.defined()) {
2320	              body.Set(i, rewritten_wait.value());
2321	              changed = true;
2322	              effective_wait_n = candidate_wait_n;
2323	            }
2324	          }
2325	        }
2326	        seen_wait_boundary = true;
2327	        outstanding_lb = std::min(outstanding_lb, effective_wait_n);
2328	        groups_since_wait_lb = 0;
2329	        continue;
2330	      }
2331	
2332	      AsyncSyncSummary summary = SummarizeAsyncSyncScopes(body[i]);
2333	      if (summary.wait == 0) {
2334	        if (auto commits = TryGetDeterministicNoWaitCommitGroups(body[i])) {
2335	          outstanding_lb += *commits;
2336	          groups_since_wait_lb += *commits;
2337	          continue;
2338	        }
2339	      }
2340	      if (summary.wait > 0) {
2341	        seen_wait_boundary = true;
2342	      }
2343	      outstanding_lb = 0;
2344	      groups_since_wait_lb = 0;
2345	    }
2346	
2347	    if (!changed) {
2348	      return loop;
2349	    }
2350	    For new_loop = loop;
2351	    new_loop.CopyOnWrite()->body = body.size() == 1 ? body[0] : SeqStmt(body);
2352	    return new_loop;
2353	  }
