2769	    for (size_t i = 0; i < new_stmts.size();) {
2770	      if (auto it = waits_before_stmt.find(i); it != waits_before_stmt.end()) {
2771	        for (const auto &[stage_id, wait_count] : it->second) {
2772	          Stmt wait_stmt = make_wait_stmt(stage_id, wait_count, Evaluate(0));
2773	          if (auto state_it = async_states_local.find(stage_id);
2774	              state_it != async_states_local.end() &&
2775	              state_it->second.predicate &&
2776	              !ana_normalized->CanProve(state_it->second.predicate.value())) {
2777	            PrimExpr predicate =
2778	                ana_normalized->Simplify(state_it->second.predicate.value());
2779	            if (is_zero(predicate)) {
2780	              continue;
2781	            }
2782	            wait_stmt = IfThenElse(predicate, wait_stmt, Evaluate(0));
2783	          }
2784	          result.push_back({new_stmts[i].stage, new_stmts[i].access_index,
2785	                            new_stmts[i].predicate, wait_stmt});
2786	        }
2787	      }
2788	
2789	      if (commit_group_tags[i] == -1) {
2790	        result.push_back(new_stmts[i]);
2791	        ++i;
2792	        continue;
2793	      }
2794	
2795	      int commit_group_tag = commit_group_tags[i];
2796	      int stage_id = commit_group_tag_to_stage.at(commit_group_tag);
2797	      Array<Stmt> group_stmts;
2798	      PrimExpr access_index = new_stmts[i].access_index;
2799	      PrimExpr predicate = new_stmts[i].predicate;
2800	      for (; i < new_stmts.size() && commit_group_tags[i] == commit_group_tag;
2801	           ++i) {
2802	        group_stmts.push_back(new_stmts[i].stmt);
2803	      }
2804	      Stmt group_body =
2805	          group_stmts.size() == 1 ? group_stmts[0] : SeqStmt(group_stmts);
2806	      Stmt commit_queue_scope =
2807	          AttrStmt(make_zero(DataType::Int(32)),
2808	                   s_tir::attr::async_commit_queue_scope, stage_id, group_body);
2809	      if (!is_one(predicate) && !ana_normalized->CanProve(predicate)) {
2810	        PrimExpr simplified_predicate = ana_normalized->Simplify(predicate);
2811	        if (!is_zero(simplified_predicate)) {
2812	          commit_queue_scope =
2813	              IfThenElse(simplified_predicate, commit_queue_scope, Evaluate(0));
2814	        }
2815	      }
2816	      result.push_back({stage_id, access_index, predicate, commit_queue_scope});
2817	    }
2818	    return result;
2819	  }
