2821	  /*!
2822	   * \brief Emit the pipeline loop in the given range.
2823	   * \param start The start of the range
2824	   * \param end The end of the range
2825	   * \param unroll_loop Whether the loop should be unrolled.
2826	   * \return The result loop.
2827	   */
2828	  Stmt EmitImpl(const PrimExpr &start, const PrimExpr &end, bool unroll_loop,
2829	                bool need_bound_check) {
2830	    PrimExpr new_loop_var;
2831	    PrimExpr extent = end - start;
2832	    Optional<Integer> pipeline_num_stages =
2833	        GetPipelineNumStages(pipeline_loop_.get());
2834	    auto make_nop = []() {
2835	      return SBlockRealize({}, Bool(true), MakeBlock(Evaluate(0), {}));
2836	    };
2837	
2838	    if (unroll_loop) {
2839	      if (const int64_t *extent_imm = as_const_int(extent)) {
2840	        if (*extent_imm > 1) {
2841	          Array<Stmt> expanded;
2842	          expanded.reserve(static_cast<size_t>(*extent_imm));
2843	          for (int64_t iter = 0; iter < *extent_imm; ++iter) {
2844	            PrimExpr unit_start =
2845	                analyzer_.Simplify(start + IntImm(extent.dtype(), iter));
2846	            PrimExpr unit_end =
2847	                analyzer_.Simplify(start + IntImm(extent.dtype(), iter + 1));
2848	            Stmt unit_stmt =
2849	                EmitImpl(unit_start, unit_end, false, need_bound_check);
2850	            expanded.push_back(unit_stmt);
2851	          }
2852	          Stmt result = expanded.size() == 1 ? expanded[0] : SeqStmt(expanded);
2853	          return result;
2854	        }
2855	      }
2856	    }
2857	
2858	    bool is_unit_loop = analyzer_.CanProveEqual(extent, 1);
2859	    if (is_unit_loop) {
2860	      new_loop_var = start; // use constants as the loop var for unit loops
2861	    } else {
2862	      new_loop_var = pipeline_loop_->loop_var.copy_with_suffix("");
2863	      // Bind the iteration domain [start, end) to strengthen analyzer facts.
2864	      analyzer_.Bind(Downcast<Var>(new_loop_var),
2865	                     Range::FromMinExtent(start, end - start));
2866	    }
2867	    // Keep the bound constraints active for all analysis below.
2868	    // Only meaningful when the loop var is symbolic (non-unit loop).
2869	    std::unique_ptr<With<arith::ConstraintContext>> ctx_lb_guard;
2870	    std::unique_ptr<With<arith::ConstraintContext>> ctx_ub_guard;
2871	    if (!is_unit_loop) {
2872	      Var loop_iter = Downcast<Var>(new_loop_var);
2873	      ctx_lb_guard.reset(
2874	          new With<arith::ConstraintContext>(&analyzer_, loop_iter >= start));
2875	      ctx_ub_guard.reset(
2876	          new With<arith::ConstraintContext>(&analyzer_, loop_iter < end));
2877	    }
2878	
2879	    arith::Analyzer ana_normalized;
2880	    if (!is_unit_loop) {
2881	      ana_normalized.Bind(Downcast<Var>(new_loop_var),
2882	                          Range(pipeline_loop_->min, extent));
2883	    }
2884	
2885	    std::vector<RewrittenStmtInfo> new_stmts;
2886	    std::map<int, AsyncStateLocal> async_states_local;
2887	    BufferCommitGroupMap buffer_to_commit_group;
2888	
2889	    for (const SBlock &block : ordered_stmts_) {
2890	      const auto &pipeline_anno = pipeline_info_.at(block);
2891	      int stage = pipeline_anno.stage;
2892	      PrimExpr inbound = Bool(true);
2893	      PrimExpr skewed_loop_var = new_loop_var - stage;
2894	      if (need_bound_check)
2895	        inbound = And(
2896	            pipeline_loop_->min <= skewed_loop_var,
2897	            (skewed_loop_var < pipeline_loop_->min + pipeline_loop_->extent));
2898	
2899	      SBlock new_block = Downcast<SBlock>(
2900	          PipelineBodyRewriter(buffer_data_to_buffer_, buffer_remap_,
2901	                               pipeline_loop_, max_stage_ != 1)(block));
2902	
2903	      PrimExpr delta = start - pipeline_loop_->min;
2904	      PrimExpr normalized_access_index =
2905	          is_unit_loop ? skewed_loop_var : skewed_loop_var + delta;
2906	
2907	      normalized_access_index = analyzer_.Simplify(normalized_access_index);
2908	
2909	      // Adjust the block predicate and the body according to the final loop
2910	      // bound
2911	      //  [pipeline_loop_->min, extent).
2912	      if (!is_unit_loop) {
2913	        Var loop_iter = Downcast<Var>(new_loop_var);
2914	        inbound = Substitute(inbound, {{loop_iter, loop_iter + delta}});
2915	      }
2916	      inbound = ana_normalized.Simplify(inbound);
2917	      if (is_zero(inbound)) {
2918	        continue;
2919	      }
2920	      new_block = Downcast<SBlock>(Substitute(
2921	          new_block, {{pipeline_loop_->loop_var, normalized_access_index}}));
2922	      new_block = ReplayScalarBindings(new_block, normalized_access_index);
2923	
2924	      Stmt rewritten_stmt = SBlockRealize({}, inbound, new_block);
2925	      Optional<PrimExpr> pipeline_mbar_phase = ComputePipelineMbarPhaseExpr(
2926	          normalized_access_index, pipeline_num_stages);
2927	
2928	      bool is_async = pipeline_anno.async;
2929	      if (is_async) {
2930	        auto &local_state = async_states_local[stage];
2931	        int commit_group_id = -1;
2932	        if (pipeline_anno.async_group_id >= 0) {
2933	          auto it = local_state.annotated_group_to_commit_group.find(
2934	              pipeline_anno.async_group_id);
2935	          if (it == local_state.annotated_group_to_commit_group.end()) {
2936	            commit_group_id = local_state.commit_groups.size();
2937	            local_state.commit_groups.push_back({new_stmts.size()});
2938	            local_state.annotated_group_to_commit_group.emplace(
2939	                pipeline_anno.async_group_id, commit_group_id);
2940	          } else {
2941	            commit_group_id = it->second;
2942	            local_state.commit_groups[commit_group_id].push_back(
2943	                new_stmts.size());
2944	          }
2945	        } else if (local_state.commit_groups.empty() || local_state.consumed) {
2946	          commit_group_id = local_state.commit_groups.size();
2947	          local_state.commit_groups.push_back({new_stmts.size()});
2948	        } else {
2949	          commit_group_id = local_state.commit_groups.size() - 1;
2950	          local_state.commit_groups.back().push_back(new_stmts.size());
2951	        }
2952	
2953	        for (const BufferRegion &write_region : new_block->writes) {
2954	          auto &global_state = async_states_[stage];
2955	          global_state.dst_buffers.insert(write_region->buffer);
2956	          global_state.buffer_to_commit_group[write_region->buffer] =
2957	              commit_group_id;
2958	          global_state.commit_group_count =
2959	              std::max(global_state.commit_group_count,
2960	                       static_cast<int>(local_state.commit_groups.size()));
2961	          buffer_to_commit_group[write_region->buffer] = commit_group_id;
2962	        }
2963	        async_states_[stage].producer_head = normalized_access_index;
2964	        local_state.producer_head = normalized_access_index;
2965	        if (!local_state.predicate ||
2966	            ana_normalized.CanProve(local_state.predicate.value())) {
2967	          local_state.predicate = inbound;
2968	        } else {
2969	          local_state.predicate =
2970	              ana_normalized.Simplify(local_state.predicate.value() & inbound);
2971	        }
2972	        rewritten_stmt = AnnotateSimtProducer(rewritten_stmt, target_);
2973	      }
2974	      if (pipeline_mbar_phase) {
2975	        rewritten_stmt = AnnotateTileOpMbarPhase(rewritten_stmt,
2976	                                                 pipeline_mbar_phase.value());
2977	      }
2978	
2979	      new_stmts.push_back({stage, inbound, new_block->reads, new_block->writes,
2980	                           normalized_access_index, is_async, rewritten_stmt});
2981	
2982	      for (const BufferRegion &read_region : new_block->reads) {
2983	        for (const auto &kv : async_states_) {
2984	          if (kv.first <= stage && kv.second.writes(read_region->buffer)) {
2985	            async_states_local[kv.first].consumed = true;
2986	          }
2987	        }
2988	      }
2989	    }
2990	
2991	    PopulateWaitCounts(new_stmts, &ana_normalized, buffer_to_commit_group,
2992	                       &async_states_local);
2993	    std::vector<FinalStmtInfo> final_stmts = CompletePipelineLoopStatements(
2994	        new_stmts, async_states_local, &ana_normalized);
2995	
2996	    Array<Stmt> stmts;
2997	    for (const auto &stmt_info : final_stmts) {
2998	      stmts.push_back(stmt_info.stmt);
2999	    }
3000	
3001	    Stmt new_loop{nullptr};
3002	
3003	    if (stmts.empty()) {
3004	      return make_nop();
3005	    }
3006	
3007	    if (stmts.size() == 1) {
3008	      new_loop = stmts[0];
3009	    } else {
3010	      new_loop = SeqStmt(stmts);
3011	    }
3012	
3013	    if (!is_unit_loop) {
3014	      Map<String, Any> preserved_annotations;
3015	      for (const auto &kv : pipeline_loop_->annotations) {
3016	        const String &key = kv.first;
3017	        if (kv.first != s_tir::attr::software_pipeline_stage &&
3018	            kv.first != s_tir::attr::software_pipeline_order &&
3019	            kv.first != s_tir::attr::software_pipeline_async_stages &&
3020	            kv.first != kPipelineAsyncProducers &&
3021	            kv.first != kPipelineAsyncProducerGroups &&
3022	            kv.first != kPipelineTmaCopies &&
3023	            kv.first != kPipelineReplayableScalarBinds &&
3024	            kv.first != "num_stages") {
3025	          preserved_annotations.Set(key, kv.second);
3026	        }
3027	      }
3028	      if (pipeline_num_stages &&
3029	          preserved_annotations.find("tl_pipelined_num_stages") ==
3030	              preserved_annotations.end()) {
3031	        preserved_annotations.Set("tl_pipelined_num_stages",
3032	                                  pipeline_num_stages.value());
3033	      }
3034	      new_loop = For(Downcast<Var>(new_loop_var), pipeline_loop_->min, extent,
3035	                     unroll_loop ? ForKind::kUnrolled : pipeline_loop_->kind,
3036	                     std::move(new_loop), std::nullopt, preserved_annotations);
3037	    }
3038	    Stmt result = SBlockRealize({}, Bool(true),
3039	                                MakeBlock(new_loop, buffer_data_to_buffer_));
