3091	  /*!
3092	   * \brief Check the pipeline satisfies the following conditions:
3093	   * 1. No conflicting order: The order of each statement should be unique.
3094	   * 2. Reordering of statements doesn't break buffer access dependencies.
3095	   * Specifically, for dependency (e.g. read-after-write) from statement A to
3096	   * statement B, it requires: case 1: stage(A) < stage(B) case 2: stage(A) ==
3097	   * stage(B) and order(A) < order(B)
3098	   */
3099	  void ValidatePipelineBody(const PipelineInfo &pipeline_info,
3100	                            const Array<SBlock> &original_order) {
3101	    std::unordered_set<int> used_orders;
3102	    for (const SBlock &block : original_order) {
3103	      const auto &stmt_info = pipeline_info.at(block);
3104	      int order = stmt_info.order;
3105	      ICHECK(!used_orders.count(order))
3106	          << "ValueError: Two statements in the software pipeline cannot have "
3107	             "the same order";
3108	      used_orders.insert(order);
3109	    }
3110	
3111	    std::unordered_map<SBlock, Array<SBlock>, ObjectPtrHash, ObjectPtrEqual>
3112	        dep_src2dst;
3113	    BuildDependencyGraph(original_order, &dep_src2dst, nullptr);
3114	
3115	    for (const auto &pair : dep_src2dst) {
3116	      const SBlock &src = pair.first;
3117	      const auto &src_info = pipeline_info.at(src);
3118	      const Array<SBlock> &dsts = pair.second;
3119	      for (const SBlock &dst : dsts) {
3120	        const auto &dst_info = pipeline_info.at(dst);
3121	        ICHECK_LE(src_info.stage, dst_info.stage)
3122	            << "ValueError: statement " << dst << " in stage " << dst_info.stage
3123	            << " cannot depends on statement " << src << " in a later stage "
3124	            << src_info.stage;
3125	        if (src_info.stage == dst_info.stage) {
3126	          ICHECK_LT(src_info.order, dst_info.order)
3127	              << "ValueError: two statements with buffer "
3128	                 "access dependency in the same stage of the "
3129	                 "software pipeline cannot be reordered";
3130	        }
3131	      }
3132	    }
3133	  }
