3135	  void ValidateScheduledBindDependencies(const PipelineInfo &pipeline_info,
3136	                                         const Array<SBlock> &scheduled_order) {
3137	    std::unordered_map<Var, SBlock, ObjectPtrHash, ObjectPtrEqual>
3138	        bind_producers;
3139	    for (const SBlock &block : scheduled_order) {
3140	      if (const auto *bind = block->body.as<BindNode>()) {
3141	        bind_producers.emplace(bind->var, block);
3142	      }
3143	    }
3144	    if (bind_producers.empty()) {
3145	      return;
3146	    }
3147	
3148	    for (const SBlock &consumer : scheduled_order) {
3149	      Array<Var> undefined_vars = UndefinedVars(consumer->body, Array<Var>{});
3150	      for (const Var &var : undefined_vars) {
3151	        auto it = bind_producers.find(var);
3152	        if (it == bind_producers.end() || it->second.same_as(consumer)) {
3153	          continue;
3154	        }
3155	
3156	        const PipelineAnnotation &producer_info = pipeline_info.at(it->second);
3157	        const PipelineAnnotation &consumer_info = pipeline_info.at(consumer);
3158	        ICHECK_EQ(producer_info.stage, consumer_info.stage)
3159	            << "ValueError: scheduled scalar Bind '" << var
3160	            << "' is used from a different pipeline stage. Scalar Bind "
3161	               "statements that cannot be replayed must be scheduled in the "
3162	               "same stage as their consumers.";
3163	        ICHECK_LT(producer_info.order, consumer_info.order)
3164	            << "ValueError: scheduled scalar Bind '" << var
3165	            << "' must be ordered before every consumer in the same pipeline "
3166	               "stage.";
3167	      }
3168	    }
3169	  }
