3194	  PipelineScheduleUnit MakePipelineScheduleUnit(const Stmt &stmt) {
3195	    PipelineScheduleUnit unit;
3196	    if (const auto *realize = stmt.as<SBlockRealizeNode>()) {
3197	      if (is_one(realize->predicate) &&
3198	          realize->block->body->IsInstance<SeqStmtNode>()) {
3199	        const SBlock &nested_block = realize->block;
3200	        ICHECK(nested_block->match_buffers.empty())
3201	            << "match_buffer should have been lowered before "
3202	               "InjectSoftwarePipeline";
3203	        for (const Buffer &buffer : nested_block->alloc_buffers) {
3204	          buffer_data_to_buffer_.Set(buffer->data, buffer);
3205	          allocated_buffers_.insert(buffer);
3206	          unit.nested_local_allocs.push_back(buffer);
3207	        }
3208	      }
3209	    }
3210	    unit.block = MakeBlock(stmt, buffer_data_to_buffer_);
3211	    return unit;
3212	  }
