3217	      PipelineScheduleUnit unit = MakePipelineScheduleUnit(stmt);
3218	      schedule.original_order.push_back(unit.block);
3219	      schedule.nested_local_allocs.insert(schedule.nested_local_allocs.end(),
3220	                                          unit.nested_local_allocs.begin(),
3221	                                          unit.nested_local_allocs.end());
3222	    }
3223	    return schedule;
