3226	  Array<Stmt> StripPipelineDeclarationStmts(const Array<Stmt> &pipeline_body,
3227	                                            Array<Buffer> *block_local_allocs,
3228	                                            Array<Buffer> *flat_local_allocs) {
3229	    ICHECK(block_local_allocs != nullptr);
3230	    ICHECK(flat_local_allocs != nullptr);
3231	    Array<Stmt> stage_stmts;
3232	    bool filtered = false;
3233	    for (const Stmt &child : pipeline_body) {
3234	      if (IsPipelineDeclarationStmt(child)) {
3235	        if (const auto *alloc = child.as<AllocBufferNode>()) {
3236	          const Buffer &buffer = alloc->buffer;
3237	          buffer_data_to_buffer_.Set(buffer->data, buffer);
3238	          allocated_buffers_.insert(buffer);
3239	          block_local_allocs->push_back(buffer);
3240	          flat_local_allocs->push_back(buffer);
3241	        } else {
3242	          const auto *decl = child.as<DeclBufferNode>();
3243	          ICHECK(decl != nullptr);
3244	          const Buffer &buffer = decl->buffer;
3245	          buffer_data_to_buffer_.Set(buffer->data, buffer);
3246	        }
3247	        filtered = true;
3248	        continue;
3249	      }
3250	      stage_stmts.push_back(child);
3251	    }
3252	    if (!filtered) {
3253	      return pipeline_body;
3254	    }
3255	    ICHECK(!stage_stmts.empty())
3256	        << "ValueError: The body of the software pipeline has no stages "
3257	           "after removing buffer declarations";
3258	    return stage_stmts;
3259	  }
